-- The service-provider catalog: 130 providers across 26 categories.
--
-- Replaces the old seed runner (scripts/seed-providers.mjs), so a database
-- built from migrations comes up with the directory filled. Exported from the
-- dev database on 2026-11-04. After launch, providers are managed through the
-- app; add a new migration only for changes that must reach a fresh build.
--
-- Safe on a database that already has these rows: each provider is inserted
-- only when no row with the same category and title exists, so on dev this
-- inserts nothing.
--
-- user_id is the label "system". Only superadmins can write services (see
-- 20260923020144), so ownership grants nothing and a fresh build has no Clerk
-- users to point at anyway.
--
-- Logos point at fixed R2 objects under service-images/catalog/, shared by
-- every environment. lib/api/upload.ts never deletes that prefix, so removing
-- a provider in one environment cannot break another environment's logo.

INSERT INTO public.services
  (user_id, created_at, updated_at, category, title, summary, details, tags,
   contact_email, contact_phone, location, website, status, image_url)
SELECT 'system', v.created_at, v.created_at, v.category, v.title, v.summary, v.details, v.tags,
       v.contact_email, v.contact_phone, v.location, v.website, v.status, v.image_url
FROM (VALUES
  ('2026-08-11T00:43:51.540007+00:00'::timestamptz, 'community-personal-services/babysitting-childcare', 'Primrose School of Chapel Hill at Briar Chapel', 'Accredited daycare and preschool on Falling Springs Drive, inside Briar Chapel itself', 'Primrose School of Chapel Hill at Briar Chapel sits on Falling Springs Drive within the Briar Chapel neighborhood, making it the closest licensed center to residents. Programs cover infants from six weeks through toddler, preschool, pre-kindergarten, kindergarten, after-school, and summer camp, taught through the Primrose Balanced Learning approach. The school is locally owned by Gaurav and Anna Sharma and sits just off the 501 corridor between Pittsboro and Chapel Hill. Every staff member is background checked and CPR and first-aid certified. Hours are Monday through Friday, 7:00 am to 6:00 pm.', ARRAY['briar-chapel', 'preschool', 'infant-care', 'pre-k', 'summer-camp']::text[], NULL, '(919) 441-0441', 'Briar Chapel, Chapel Hill, NC', 'https://www.primroseschools.com/schools/chapel-hill-at-briar-chapel', 'active', NULL),
  ('2026-08-11T00:43:51.675362+00:00'::timestamptz, 'community-personal-services/babysitting-childcare', 'Chapel Hill Day Care Center', 'Five-star, NAEYC-accredited center in Southern Village for ages 8 weeks to 5 years', 'Chapel Hill Day Care Center is a full-day early childhood education program on Kildaire Road in Southern Village, serving children from 8 weeks old through age 5. It holds a five-star rating and is accredited by the National Association for the Education of Young Children, operating under NC License #68000135. The program is relationship-based and uses an evidence-based curriculum spanning infant, toddler, preschool, and pre-K classrooms. Its Southern Village location gives families access to the Park & Ride, the community playground, and nearby shops. Hours are Monday through Friday, 7:30 am to 5:30 pm.', ARRAY['five-star', 'naeyc-accredited', 'infant-care', 'southern-village', 'licensed']::text[], 'chdccdirector@gmail.com', '(919) 929-3585', 'Chapel Hill, NC', 'http://www.chapelhilldaycarecenter.com/', 'active', NULL),
  ('2026-08-11T00:43:51.794477+00:00'::timestamptz, 'community-personal-services/babysitting-childcare', 'Community School for People under Six', 'Five-star Carrboro center operating since 1970 with a multicultural, community-based curriculum', 'Community School for People under Six has educated infants, toddlers, and preschoolers in Carrboro since 1970 from its Hargraves Street location. It is a five-star licensed child care center and an NC Pre-Kindergarten program, serving ages 2 months through 8 years and licensed to include students up to age 12. The curriculum is creative, community-based, and multicultural, and the school explicitly prioritizes access for low- and middle-income families while promoting cultural, racial, gender, and socioeconomic diversity. It also provides advanced educational opportunities for its teachers.', ARRAY['five-star', 'nc-pre-k', 'multicultural', 'nonprofit', 'established']::text[], NULL, '(919) 929-1543', 'Carrboro, NC', 'https://cspu6.org/', 'active', NULL),
  ('2026-08-11T00:43:51.919717+00:00'::timestamptz, 'community-personal-services/babysitting-childcare', 'Chapel Hill Cooperative Preschool', 'Chapel Hill''s longest-running independent nonprofit preschool, five-star and NAEYC accredited', 'Chapel Hill Cooperative Preschool on Mount Carmel Church Road is the longest-running independent, non-profit preschool in Chapel Hill, founded in 1960. It is one of a small number of preschools in town that are both five-star rated and NAEYC accredited. As a cooperative, the school involves parents directly in the program alongside its teaching staff. Enrollment tends to run well ahead of the school year and families frequently join a waitlist, so early inquiry is advisable.', ARRAY['cooperative', 'nonprofit', 'five-star', 'naeyc-accredited', 'parent-participation']::text[], NULL, '(919) 942-3955', 'Chapel Hill, NC', 'https://www.chapelhillcoop.com/', 'active', NULL),
  ('2026-08-11T00:43:52.038224+00:00'::timestamptz, 'community-personal-services/babysitting-childcare', 'The Goddard School of Chapel Hill', 'Accredited preschool and daycare on Martin Luther King Jr. Boulevard, open 7am to 6pm', 'The Goddard School of Chapel Hill is an accredited preschool and daycare on Martin Luther King Jr. Boulevard north of downtown. It follows the Goddard play-based learning approach across infant, toddler, preschool, and pre-kindergarten programs. The school operates Monday through Friday from 7:00 am to 6:00 pm, which accommodates full working days. It is one of the more centrally located options for families commuting toward Hillsborough or I-40.', ARRAY['preschool', 'daycare', 'play-based', 'accredited', 'full-day']::text[], NULL, '(919) 933-9022', 'Chapel Hill, NC', 'https://www.goddardschool.com/schools/nc/chapel-hill/chapel-hill', 'active', NULL),
  ('2026-08-11T00:44:04.64302+00:00'::timestamptz, 'community-personal-services/elder-care-senior-assistance', 'Senior Helpers of Chapel Hill', 'Licensed in-home senior care based in Chatham Park, Pittsboro, minutes from Briar Chapel', 'Senior Helpers of Chapel Hill operates from Russet Run in Chatham Park, Pittsboro, making it the closest licensed home care agency to Briar Chapel. Services range from companion care for seniors who need daily support through specialized care for Alzheimer’s, dementia, Parkinson’s, and other chronic illnesses. The agency is owned and operated by Todd and Ben Rogers, and its caregivers and staff live in the greater Pittsboro area. It holds North Carolina home care license #HC8347 and is reachable around the clock. Service area covers Durham, Chapel Hill, Carrboro, Pittsboro, and Sanford.', ARRAY['licensed', 'pittsboro', 'dementia-care', 'companion-care', '24-hour']::text[], 'clients_3741@seniorhelpers.com', '(919) 503-5805', 'Pittsboro, NC', 'https://www.seniorhelpers.com/nc/chapel-hill/', 'active', NULL),
  ('2026-08-11T00:44:04.708684+00:00'::timestamptz, 'community-personal-services/elder-care-senior-assistance', 'Home Instead Chapel Hill', 'Non-medical in-home care serving Chapel Hill since 1997 across Orange, Chatham, and Durham counties', 'Home Instead has served Chapel Hill since 1997 and has provided more than 850,000 hours of in-home care to local families. Care Pros deliver non-medical support ranging from meal preparation and companionship through memory-loss support and transportation to UNC Health appointments. Most clients begin receiving care within 48 hours of contact, and many stay with the agency for two and a half years or longer. Coverage extends across Orange, Chatham, and Durham counties, including Chapel Hill, Carrboro, Pittsboro, Hillsborough, Mebane, Efland, and Cedar Grove. Free consultations are available before a care plan is built.', ARRAY['established', 'non-medical', 'memory-care', 'companionship', 'transportation']::text[], NULL, '(919) 933-3300', 'Chapel Hill, NC', 'https://www.homeinstead.com/home-care/usa/nc/chapel-hill/106/', 'active', NULL),
  ('2026-08-11T00:44:04.772559+00:00'::timestamptz, 'community-personal-services/elder-care-senior-assistance', 'Visiting Angels of Chapel Hill', 'One-on-one home care from a Carrboro office serving Orange, Durham, Chatham, and Alamance counties', 'Visiting Angels of Chapel Hill works out of an office on Jones Ferry Road in Carrboro and provides customizable, one-on-one in-home care plans for seniors. The agency covers Orange, Durham, Chatham, and Alamance counties. Care plans are built around each client rather than fitted to a fixed package, and caregivers are screened before placement. Families can call to discuss options before committing to a schedule.', ARRAY['one-on-one', 'carrboro', 'custom-care-plans', 'chatham-county', 'in-home']::text[], NULL, '(919) 321-2136', 'Carrboro, NC', 'https://www.visitingangels.com/chapelhill/home', 'active', NULL),
  ('2026-08-11T00:44:04.835949+00:00'::timestamptz, 'community-personal-services/elder-care-senior-assistance', 'Homewatch CareGivers of Chapel Hill', 'In-home care with dementia and injury-recovery specialization, from respite to 24-hour support', 'Homewatch CareGivers of Chapel Hill provides in-home care spanning part-time respite through around-the-clock coverage. Services include elder care, dementia care, chronic conditions care, transitional care after a hospital stay, personal care, and transportation. Caregivers receive condition-specific training for dementia, Alzheimer’s, Parkinson’s, and other chronic illnesses. All caregivers are trained, background-checked, and insured, and the location is licensed per state and local requirements.', ARRAY['dementia-care', 'respite-care', '24-hour', 'transitional-care', 'insured']::text[], NULL, '(919) 289-3270', 'Chapel Hill, NC', 'https://www.homewatchcaregivers.com/chapel-hill/', 'active', NULL),
  ('2026-08-11T00:44:04.900255+00:00'::timestamptz, 'community-personal-services/elder-care-senior-assistance', 'Always Best Care of Chapel Hill & Durham', 'Non-medical senior care with CNAs on staff, offering hourly, overnight, and live-in schedules', 'Always Best Care of Chapel Hill & Durham operates from Legion Road and specializes in non-medical care for seniors who want to remain in their own homes. The agency maintains a large team of Certified Nursing Assistants and trained caregivers, and staffing coordinators arrange hourly, overnight, or live-in schedules. Each client receives an individualized care plan to keep service consistent. All caregivers are bonded, insured, background checked, and drug tested. The agency also offers an assisted living placement service for families weighing senior housing options.', ARRAY['cna-staff', 'live-in-care', 'overnight', 'bonded-insured', 'placement-service']::text[], NULL, '(336) 270-4352', 'Chapel Hill, NC', 'https://alwaysbestcare.com/chapel-hill/', 'active', NULL),
  ('2026-08-11T00:44:14.095836+00:00'::timestamptz, 'community-personal-services/music-art-teachers', 'Chapel Hill School of Musical Arts', 'Private music lessons, studio classes, and recitals on East Franklin Street', 'Chapel Hill School of Musical Arts is a music school on East Franklin Street offering private lessons across instruments and voice. The program extends past the standard weekly lesson to include studio classes, recitals, workshops, master classes, and other performance opportunities, so students get regular experience playing in front of others. The school works from the premise that anyone can learn to play or sing, and takes students across ages and levels. Prospective families start with a consultation to be matched with a teacher.', ARRAY['music-lessons', 'private-lessons', 'recitals', 'workshops', 'all-ages']::text[], NULL, '(919) 960-6898', 'Chapel Hill, NC', 'https://chapelhillschoolofmusicalarts.com/', 'active', NULL),
  ('2026-08-11T00:44:14.191584+00:00'::timestamptz, 'community-personal-services/music-art-teachers', 'School of Rock Chapel Hill', 'Performance-based music program on North Fordham Boulevard for guitar, bass, drums, keys, and vocals', 'School of Rock Chapel Hill on North Fordham Boulevard teaches through a performance-based model that combines private lessons with group band rehearsals, so students apply what they learn by playing with other musicians. Instruction covers guitar, bass, drums, keyboard, and vocals, with programs for a range of ages and skill levels. The school also runs music camps and workshops, including songwriting and learning to play in a band. Weekday hours run into the evening, which works around school schedules.', ARRAY['music-lessons', 'band-program', 'performance', 'camps', 'guitar-drums-vocals']::text[], NULL, '(919) 338-1011', 'Chapel Hill, NC', 'https://www.schoolofrock.com/locations/chapelhill', 'active', NULL),
  ('2026-08-11T00:44:14.306876+00:00'::timestamptz, 'community-personal-services/music-art-teachers', 'Creative Music Instruction', 'Private music instruction in downtown Carrboro, serving the community since 1997', 'Creative Music Instruction has offered private music lessons to the Chapel Hill and Carrboro community since 1997 from its studio on West Main Street in downtown Carrboro. Lessons are tailored to the individual interests and goals of each student rather than following a fixed syllabus, and are taught in a friendly, relaxed atmosphere. Instruction covers instruments including piano and keyboard as well as drum set and percussion. The instructors treat their role as mentorship as much as teaching. The studio prefers text contact for initial inquiries.', ARRAY['music-lessons', 'carrboro', 'piano', 'drums', 'established']::text[], NULL, '(919) 448-7049', 'Carrboro, NC', 'https://www.createinstruct.com/', 'active', NULL),
  ('2026-08-11T00:44:14.422696+00:00'::timestamptz, 'community-personal-services/music-art-teachers', 'Cely''s House Creative Workshops', 'Pottery and art classes, after-school programs, and summer camps on Dixie Drive since 2000', 'Cely''s House on Dixie Drive was founded in 2000 by Chapel Hill natives Bill and Cely Chicurel and has specialized in art and creative workshops for over 25 years. The studio offers pottery classes for all ages in both hand-building and wheel throwing, after-school art programs, summer art camps, birthday parties, and retreats. Cely holds a degree in pottery and weaving and has further study at the Penland and Arrowmont schools of arts and crafts. After-school pottery and art classes run Monday through Friday from 3:30 to 5:30 pm, with open studio time for adults several mornings a week. Painting classes are offered separately, and most Friday nights the studio is open for parents and children to make art together.', ARRAY['pottery', 'art-classes', 'after-school', 'summer-camp', 'all-ages']::text[], NULL, '(919) 225-7349', 'Chapel Hill, NC', 'https://www.celyshouse.net/', 'active', NULL),
  ('2026-08-11T00:44:14.520605+00:00'::timestamptz, 'community-personal-services/music-art-teachers', 'The ArtsCenter ArtSchool', 'Quarterly art classes in Carrboro across drawing, painting, ceramics, fiber arts, and more', 'The ArtsCenter in Carrboro runs ArtSchool, a quarterly class program for adults and teens spanning drawing, painting, mixed media, ceramics, fiber arts, stained glass, dance, theatre, photography, writing, and arts-based wellness. New sessions open each winter, spring, summer, and fall. Registration can be completed online, by phone during business hours, or in person, and the staff will help match you to a class. Classes with strong demand fill quickly, so registering in advance is recommended. Classes that fall short on enrollment are cancelled one to three days ahead with a full refund.', ARRAY['art-classes', 'ceramics', 'painting', 'carrboro', 'adults-teens']::text[], 'artschool@artscenterlive.org', '(919) 929-2787', 'Carrboro, NC', 'https://artscenterlive.org/artschool-classes/', 'active', NULL),
  ('2026-08-11T00:44:23.72933+00:00'::timestamptz, 'community-personal-services/personal-trainers-fitness', 'O2 Fitness Briar Chapel', 'Full-service Signature club on Market Chapel Road with personal training, classes, and childcare', 'O2 Fitness Briar Chapel is a full-service Signature Club on Market Chapel Road just off Highway 15-501, serving members from Chapel Hill, Carrboro, Pittsboro, and northern Chatham County. The facility includes a cardio deck overlooking the strength-training area, a quieter cardio theater, and an indoor turf area for functional training. Membership covers unlimited group fitness classes, access to all O2 Fitness locations, and two complimentary personal training sessions. Additional amenities include a Kids Club for childcare during workouts, a coworking space, physiotherapy, and nutrition counseling. Hours are Monday through Thursday 5am to 10pm, Friday 5am to 9pm, and weekends 7am to 7pm. Daily, weekly, and monthly guest passes are available.', ARRAY['briar-chapel', 'full-service-gym', 'group-fitness', 'personal-training', 'childcare']::text[], NULL, '(919) 942-6002', 'Briar Chapel, Pittsboro, NC', 'https://o2fitnessclubs.com/', 'active', NULL),
  ('2026-08-11T00:44:23.792707+00:00'::timestamptz, 'community-personal-services/personal-trainers-fitness', 'FIT Carrboro', 'Personal training, group training, and Pilates studio on East Main Street in Carrboro', 'FIT Carrboro is a personal training and Pilates studio on East Main Street in downtown Carrboro. The studio offers one-on-one personalized training, group training, virtual training, and Pilates reformer classes, along with community events for members. Its trainers bring more than 180 years of combined experience and work from a stated client-first, do-no-harm approach, building individualized programming around each person rather than a fixed template. Programs are designed to be appropriate to the individual regardless of starting fitness level.', ARRAY['personal-training', 'pilates', 'group-training', 'carrboro', 'virtual-training']::text[], NULL, '(919) 590-0892', 'Carrboro, NC', 'https://www.fitcarrboro.com/', 'active', NULL),
  ('2026-08-11T00:44:23.863747+00:00'::timestamptz, 'community-personal-services/personal-trainers-fitness', 'Fitness Together Chapel Hill', 'Private one-on-one personal training in individual workout suites at Meadowmont Village', 'Fitness Together Chapel Hill is a personal training studio in Meadowmont Village Circle built around private workout suites rather than an open gym floor. Every session is one-on-one with a trainer, either in-studio or virtually. New clients start with a complimentary fit evaluation so the trainer can understand their goals and starting point before building a custom program. The private-suite format suits people who prefer not to train in a crowded gym environment, and programs are designed to work at any age or fitness level.', ARRAY['one-on-one', 'private-suites', 'meadowmont', 'custom-programs', 'virtual-training']::text[], NULL, '(919) 932-7303', 'Chapel Hill, NC', 'https://www.fitnesstogether.com/chapelhill', 'active', NULL),
  ('2026-08-11T00:44:23.935+00:00'::timestamptz, 'community-personal-services/personal-trainers-fitness', 'F45 Training East Chapel Hill', 'Team-based functional interval training studio on Fordham Boulevard', 'F45 Training East Chapel Hill runs the F45 team training format from a studio on Fordham Boulevard. Workouts are 45-minute functional circuits combining resistance and cardiovascular work, led by coaches in a group setting with rotating daily programming so sessions do not repeat. The team-based structure suits people who prefer accountability and a set class time over designing their own workouts. A seven-day trial is available for new members.', ARRAY['group-training', 'hiit', 'functional-fitness', '45-minute', 'trial-available']::text[], NULL, '(919) 895-3851', 'Chapel Hill, NC', 'https://f45training.com/studio/eastchapelnc', 'active', NULL),
  ('2026-08-11T00:44:23.998414+00:00'::timestamptz, 'community-personal-services/personal-trainers-fitness', 'FlowCorps', 'Movement and fitness studio on South Elliott Road in Chapel Hill', 'FlowCorps operates a movement and fitness studio on South Elliott Road in Chapel Hill. The studio focuses on coached movement and strength work rather than open-gym access, working with clients across a range of experience levels. Pricing and current class offerings are shared by phone, so calling ahead is the best way to find out what fits your schedule and goals.', ARRAY['movement', 'strength', 'coached', 'chapel-hill', 'small-studio']::text[], NULL, '(919) 525-3989', 'Chapel Hill, NC', 'https://flowcorps.com/', 'active', NULL),
  ('2026-08-11T00:44:33.987342+00:00'::timestamptz, 'community-personal-services/tutoring-after-school', 'Sylvan Learning of Chapel Hill', 'K-12 tutoring and test prep at Governors Drive, also serving Chatham County', 'Sylvan Learning of Chapel Hill operates from Governors Drive and covers K-12 tutoring, college and career readiness, and test preparation. Instruction starts with the Sylvan Insight assessment, which establishes where a student currently stands before a personalized plan is built. Tutors are selected in part for their familiarity with local curriculum so lessons connect to what students are covering in Chapel Hill schools. The center lists Chatham County, Chapel Hill, Carrboro, and Orange County in its service area, and is open weekdays with Saturday morning hours.', ARRAY['k-12', 'test-prep', 'assessment', 'reading', 'math']::text[], NULL, '(984) 333-9979', 'Chapel Hill, NC', 'https://www.sylvanlearning.com/locations/us/nc/chapel-hill-tutoring/chapel-hill/', 'active', NULL),
  ('2026-08-11T00:44:34.057164+00:00'::timestamptz, 'community-personal-services/tutoring-after-school', 'Mathnasium of Chapel Hill', 'Math-only learning center on Fordham Boulevard for K-12 students, in-center or online', 'Mathnasium of Chapel Hill is a learning center on Fordham Boulevard that focuses exclusively on mathematics for K-12 students. The Mathnasium Method begins with an assessment that identifies specific gaps, then builds a customized learning plan rather than following a fixed curriculum. Sessions are available both in-center and online. Because the center specializes rather than covering all subjects, it is a strong fit for students whose difficulty is concentrated in math.', ARRAY['math', 'k-12', 'assessment', 'in-center', 'online']::text[], NULL, '(919) 490-5151', 'Chapel Hill, NC', 'https://www.mathnasium.com/math-centers/chapelhill', 'active', NULL),
  ('2026-08-11T00:44:34.119382+00:00'::timestamptz, 'community-personal-services/tutoring-after-school', 'Clinical Teaching Tutors', 'Long-established local tutoring and academic coaching practice serving the area since 1968', 'Clinical Teaching has provided tutoring and academic coaching in Chapel Hill and the Triangle since 1968, operating from Franklin Square on East Franklin Street. Services span academic coaching seven days a week, coaching for students with ADHD, learning differences, and dyslexia, homework and study support, ESL, and test preparation for the SAT, ACT, PSAT, SSAT, ISEE, GRE, PRAXIS, and end-of-grade and end-of-course exams. The practice also supports AP and honors coursework, offers school advocacy consulting, and serves as an approved distance testing site. Tutoring can take place at their office, a student home, a school, or a library.', ARRAY['established', 'academic-coaching', 'adhd-support', 'test-prep', 'esl']::text[], 'jlocts@aol.com', '(919) 967-5776', 'Chapel Hill, NC', 'http://www.clinicalteachingtutors.com/services', 'active', NULL),
  ('2026-08-11T00:44:34.182992+00:00'::timestamptz, 'community-personal-services/tutoring-after-school', 'The Princeton Review - Chapel Hill', 'Test prep courses and private tutoring from a local office on North Merritt Mill Road', 'The Princeton Review maintains a Chapel Hill office on North Merritt Mill Road inside the 27516 ZIP code. Programs cover tutoring in math, science, English, and social studies alongside homework help, plus test preparation for the ACT, SAT, PSAT, AP exams, SSAT, ISEE, TOEFL, and graduate exams including the GRE, GMAT, LSAT, and MCAT. Courses are offered both in person and online. Enrollment runs through a national line rather than the local office directly.', ARRAY['test-prep', 'sat-act', 'graduate-exams', 'in-person', 'online']::text[], NULL, '(800) 273-8439', 'Chapel Hill, NC', 'https://www.princetonreview.com/locations/us/north-carolina/chapel-hill-nc', 'active', NULL),
  ('2026-08-11T00:44:34.250765+00:00'::timestamptz, 'community-personal-services/tutoring-after-school', 'RENA Community Center After-School Tutoring', 'Free after-school tutoring for grades 1-10 run by the Rogers-Eubanks Neighborhood Association', 'The Rogers-Eubanks Neighborhood Association Community Center on Edgar Street runs a free after-school tutoring program for roughly 30 students in grades 1 through 10, covering math, reading, spelling, and end-of-grade test preparation. The program is overseen by Karen Reid, an award-winning retired teacher from the Chapel Hill-Carrboro City School District, and most tutors are UNC students. Staff coordinate directly with each student’s teachers and counselor to target the areas needing the most help. Sessions run mid-September through the first week of May, Monday through Thursday from 3:00 to 5:30 pm, with snacks included. Beginning in February the focus shifts to end-of-grade test preparation, with pre- and post-testing to measure progress.', ARRAY['free', 'nonprofit', 'after-school', 'eog-prep', 'grades-1-10']::text[], NULL, NULL, 'Chapel Hill, NC', 'https://www.renacommunitycenter.com/after-school-tutoring', 'active', NULL),
  ('2026-08-11T00:56:30.768014+00:00'::timestamptz, 'food-hospitality/food-delivery-catering', 'The Catering Company of Chapel Hill', 'The Triangle''s oldest continually operating caterer, established in 1980', 'Established in 1980, The Catering Company of Chapel Hill is the oldest continually operating caterer in the Triangle, with more than four decades of events behind it. The company handles full-service catering and event management for weddings, corporate gatherings, university events, and celebrations of all sizes across the Triangle and throughout North Carolina. Its chefs and event planners work with clients to build both a menu and a service style, and the team also covers beverages and event decor. It suits clients who want a single vendor managing the details rather than coordinating several.', ARRAY['full-service', 'weddings', 'corporate', 'event-management', 'established-1980']::text[], NULL, '(919) 929-4775', 'Chapel Hill, NC', 'https://www.thecateringcompanych.com/', 'active', NULL),
  ('2026-08-11T00:56:30.852188+00:00'::timestamptz, 'food-hospitality/food-delivery-catering', '39 West Catering', 'Pittsboro caterer launched in 2015, on the Chatham County approved caterer list', '39 West Catering was launched in 2015 by Executive Chef Greg Lewis and his wife Maria Parker-Lewis, and is based in Pittsboro. The team specializes in flexible, creative catering across a wide range of cuisines and dietary needs, handling everything from live stations to boxed lunches to afternoon snacks for weddings, corporate events, and family milestones. Services include bartending, table settings, and complimentary cake cutting. The same owners also run The Sycamore at Chatham Mills and Forest Hall, both in downtown Pittsboro, and are active supporters of Chatham County business and non-profit communities. The company appears on the Chatham County approved caterer list.', ARRAY['pittsboro', 'weddings', 'corporate', 'chatham-county', 'bartending']::text[], NULL, '(919) 542-2432', 'Pittsboro, NC', 'https://39westcatering.com/', 'active', NULL),
  ('2026-08-11T00:56:30.925317+00:00'::timestamptz, 'food-hospitality/food-delivery-catering', 'Beau Catering', 'Full-service catering and meal delivery on Weaver Dairy Road in Chapel Hill', 'Beau Catering operates from Weaver Dairy Road in Chapel Hill as a full-service catering and meal delivery company. It serves Chapel Hill, Durham, Hillsborough, and surrounding areas in the Triangle. The combination of event catering and meal delivery under one roof makes it a fit for both one-off gatherings and recurring food needs.', ARRAY['full-service', 'meal-delivery', 'chapel-hill', 'events', 'local']::text[], NULL, '(984) 312-5485', 'Chapel Hill, NC', 'https://www.beaucatering.com/main', 'active', NULL),
  ('2026-08-11T00:56:30.991109+00:00'::timestamptz, 'food-hospitality/food-delivery-catering', 'The Root Cellar Cafe & Catering', 'Scratch-made catering from a cafe with locations in both Chapel Hill and Pittsboro', 'The Root Cellar Cafe & Catering runs two locations, one on Martin Luther King Jr. Boulevard in Chapel Hill and one at Penguin Place on Suttles Road in Pittsboro, which puts it on both sides of Briar Chapel. Everything is scratch-made, with sandwiches, soups, salads, and desserts built from North Carolina farm ingredients wherever possible. The Chapel Hill cafe serves daily from 8am to 3pm, while the Pittsboro location runs lunch Wednesday through Friday, dinner Thursday through Saturday, and Sunday brunch. The catering arm handles events alongside the cafes, and it appears on the Chatham County approved caterer list.', ARRAY['scratch-made', 'local-farms', 'two-locations', 'pittsboro', 'cafe']::text[], NULL, '(919) 967-3663', 'Chapel Hill, NC', 'https://rootcellarchapelhill.com/', 'active', NULL),
  ('2026-08-11T00:56:31.059808+00:00'::timestamptz, 'food-hospitality/food-delivery-catering', 'Mediterranean Deli, Bakery & Catering', 'Long-running West Franklin Street deli with a large catering operation', 'Mediterranean Deli on West Franklin Street in Chapel Hill pairs a well-established deli and bakery with a substantial catering operation, and is one of the better-known catering names in town. The menu is built around Mediterranean and Middle Eastern dishes, which makes it a strong option for groups with vegetarian and vegan guests to accommodate. It is included on the Chatham County approved caterer list, so it can serve events at Chatham County venues near Briar Chapel.', ARRAY['mediterranean', 'vegetarian-friendly', 'bakery', 'chapel-hill', 'chatham-approved']::text[], NULL, '(919) 967-2666', 'Chapel Hill, NC', 'https://www.mediterraneandeli.com/', 'active', NULL),
  ('2026-08-11T00:56:20.818505+00:00'::timestamptz, 'food-hospitality/local-restaurants-cafes', 'Breakaway Cafe', 'Coffee shop and cafe in the Veranda, opened in 2016 by Briar Chapel residents', 'Breakaway Cafe sits on Chapelton Court in the Veranda at Briar Chapel and was opened in the fall of 2016 by Andy and Amy, who live in the neighborhood themselves. The pair met working at a coffee shop in the late 1990s and bonded over single-origin coffees, and built Breakaway on the premise of great food, great drinks, and great people after noticing the neighborhood had nowhere nearby to get either. Many residents treat it as a third place alongside home and work. A second location later opened in Carrboro, though the two locations run different menus. Hours are Monday through Friday 8am to 9pm, Saturday 8am to 3pm, and Sunday 8am to 2pm, with online ordering available.', ARRAY['briar-chapel', 'coffee', 'cafe', 'breakfast', 'locally-owned']::text[], NULL, '(984) 234-3010', 'Briar Chapel, Chapel Hill, NC', 'https://breakawaync.co/', 'active', NULL),
  ('2026-08-11T00:56:20.922813+00:00'::timestamptz, 'food-hospitality/local-restaurants-cafes', 'Capp''s Pizzeria & Trattoria', 'Family-run wood-fired pizzeria on Falling Springs Drive in the Veranda shops', 'Capp''s Pizzeria & Trattoria is a family-run artisan pizzeria on Falling Springs Drive in the Veranda shops at the US 15-501 entrance to Briar Chapel. The kitchen turns out seasonal wood-fired Neo-Neapolitan pizzas alongside New Haven style apizza, house-made pastas, fresh salads, and desserts, built around seasonal ingredients. Ordering is available online or by phone for pickup, with pickup windows quoted within about 15 minutes. The restaurant is closed Mondays and open Tuesday through Sunday from 4:00 pm to 8:00 pm.', ARRAY['briar-chapel', 'pizza', 'wood-fired', 'italian', 'family-run']::text[], NULL, '(919) 240-4104', 'Briar Chapel, Chapel Hill, NC', 'https://cappspizzeria.com/', 'active', NULL),
  ('2026-08-11T00:56:21.010559+00:00'::timestamptz, 'food-hospitality/local-restaurants-cafes', 'Town Hall Burger & Beer - Briar Chapel', 'Burger joint on Chapelton Court, open daily for dine-in and takeout', 'Town Hall Burger & Beer operates a Briar Chapel location on Chapelton Court in the Veranda, serving burgers and beer for both dine-in and takeout. It is one of the anchor spots in what Briar Chapel describes as the front porch of the community, where residents can grab a burger, have a drink by the outdoor fireplace, or catch live music. Hours run Monday through Saturday 11:00 am to 9:00 pm and Sunday 11:00 am to 8:00 pm.', ARRAY['briar-chapel', 'burgers', 'beer', 'dine-in', 'takeout']::text[], NULL, '(984) 234-3504', 'Briar Chapel, Chapel Hill, NC', 'https://www.townhallburgerandbeer.com/briar-chapel', 'active', NULL),
  ('2026-08-11T00:56:21.085587+00:00'::timestamptz, 'food-hospitality/local-restaurants-cafes', 'O''Ya Cantina', 'Cantina in the Briar Chapel Veranda from the founders of Town Hall Burger & Beer', 'O''Ya Cantina opened in the Veranda at Briar Chapel in 2020 and comes from the same founders behind Town Hall Burger & Beer. It rounds out the Veranda dining lineup alongside Breakaway Cafe, Capp''s Pizzeria, and Town Hall, giving residents a fourth option without leaving the neighborhood. Orders can be placed through the restaurant website or by phone.', ARRAY['briar-chapel', 'cantina', 'mexican', 'takeout', 'veranda']::text[], NULL, '(984) 999-4129', 'Briar Chapel, Chapel Hill, NC', 'https://www.briarchapelnc.com/shop-dine/', 'active', NULL),
  ('2026-08-11T00:56:21.1702+00:00'::timestamptz, 'food-hospitality/local-restaurants-cafes', 'Fearrington Village', 'Fine dining, cafe, and village shops in Pittsboro, a short drive down 15-501', 'Fearrington Village sits in the countryside between Briar Chapel and Pittsboro and has been a destination for more than 50 years. The property includes The Fearrington House Restaurant for fine dining with paired wines, an inn, a spa, and a cluster of village shops that includes one of the South’s most respected independent bookstores. It also hosts weddings and special events through a dedicated banquet and events team. The Village Shops are open Wednesday through Sunday from 10am to 5pm. It is the closest special-occasion dining to the neighborhood.', ARRAY['fine-dining', 'pittsboro', 'special-occasion', 'inn', 'shops']::text[], NULL, '(919) 542-2121', 'Pittsboro, NC', 'https://fearrington.com/', 'active', NULL),
  ('2026-08-11T00:56:40.225721+00:00'::timestamptz, 'food-hospitality/meal-prep-private-chefs', 'The Travelling Cafe', 'Personal chef service for special dietary needs, explicitly serving Pittsboro and Chapel Hill', 'The Travelling Cafe is a collective of personal chefs offering chef-prepared meals, dinner parties, and private cooking classes, with a stated service area that includes Chapel Hill, Carrboro, Pittsboro, Hillsborough, Durham, Cary, Apex, and Raleigh. The kitchen specializes in globally inspired menus built around dietary restrictions, with chefs trained for food allergies, AIP and autoimmune protocol, vegetarian, vegan, paleo, ketogenic, and low FODMAP diets. Service begins with a food questionnaire and an assessment, after which meals are cooked in your home or delivered, then packaged and labeled for quick finishing. Plans run weekly, bi-weekly, or monthly, and pricing is published on the website starting around $325 plus groceries for six meals. New clients save 15 percent when paying monthly in advance.', ARRAY['dietary-needs', 'allergy-friendly', 'pittsboro', 'cooking-classes', 'published-pricing']::text[], 'leslie@thetravellingcafe.com', '(919) 444-2840', 'Chapel Hill, NC', 'https://thetravellingcafe.com/', 'active', NULL),
  ('2026-08-11T00:56:40.29239+00:00'::timestamptz, 'food-hospitality/meal-prep-private-chefs', 'Custom Chef NC', 'ServSafe licensed and insured personal chef service with weekly, bi-weekly, or monthly visits', 'Custom Chef NC provides personal chef service where the chef shops for fresh ingredients, cooks a week of meals in your own kitchen, and cleans up afterward. The service is ServSafe licensed and fully insured. Sessions can be booked weekly, bi-weekly, or monthly with no long-term contract required. Menus can be selected from an existing list or fully customized, and the kitchen accommodates low sodium, diabetic, gluten free, and other dietary requirements. The company notes this suits seniors who need meals matched to a specific diet, and it also handles event catering. Free quotes are available by phone.', ARRAY['servsafe-licensed', 'insured', 'no-contract', 'dietary-accommodations', 'in-home']::text[], NULL, '(919) 937-0665', 'Chapel Hill, NC', 'https://customchefnc.com/services/personal-chef/', 'active', NULL),
  ('2026-08-11T00:56:40.363102+00:00'::timestamptz, 'food-hospitality/meal-prep-private-chefs', 'Kristen Russell, Personal Chef', 'Weekly meal prep and private dinners for Triangle families, cooked in your home', 'Kristen Russell is a personal chef working across the Triangle, offering weekly meal prep alongside private dinner parties and special-occasion meals. Her weekly service covers planning, cooking, and organizing healthy dinners in the client’s own kitchen, with menus that rotate rather than repeat so families are regularly introduced to new ingredients. Client reviews consistently note that she handles all dishes and trash and leaves the kitchen as she found it. She also takes on smaller elegant dinners, including multi-course birthday meals with personalized menus.', ARRAY['weekly-meal-prep', 'dinner-parties', 'in-home', 'rotating-menus', 'triangle']::text[], NULL, '(919) 504-6640', 'Chapel Hill, NC', 'https://www.chefkristenr.com/', 'active', NULL),
  ('2026-08-11T00:56:40.429879+00:00'::timestamptz, 'food-hospitality/meal-prep-private-chefs', 'Camellia Culinary', 'Nutritionally tailored in-home meal prep service based in Chapel Hill', 'Camellia Culinary is a Chapel Hill in-home meal prep service built around nutritionally tailored menus, run by Lisa and Elizabeth. Clients book on a weekly, biweekly, or monthly basis, and the team works to match both dietary requirements and family preferences rather than offering a fixed menu. Reviews describe work spanning macro-friendly meal prep for athletes through family cooking for households with young children. The business also runs a bake shop alongside its kitchen service. Inquiries go through the contact form on the website.', ARRAY['nutrition-focused', 'in-home', 'chapel-hill', 'bake-shop', 'custom-menus']::text[], NULL, NULL, 'Chapel Hill, NC', 'https://camelliaculinary.org/', 'active', NULL),
  ('2026-08-11T00:56:40.495213+00:00'::timestamptz, 'food-hospitality/meal-prep-private-chefs', 'Your Painted Plate', 'Weekly chef-prepared meal delivery in Chapel Hill, limited to a small client roster', 'Your Painted Plate provides weekly meal delivery in Chapel Hill for a deliberately limited number of households, so the chef can build around each client’s routine and preferences over time. Meals are prepared in the chef’s own kitchen, delivered, and organized for immediate use, refrigeration, and freezing with instructions for the week. The Meal Prep Flow approach builds each week from a few core proteins, vegetables, and sauces that recombine across meals, producing variety without excess complexity. The chef has over six years of experience with a background that includes Eleven Madison Park, Dominique Ansel, and École Ducasse, plus vegan recipe development work. Service runs on a monthly retainer and begins with a paid consultation that is credited toward the first month.', ARRAY['meal-delivery', 'weekly', 'limited-clients', 'gourmet', 'monthly-retainer']::text[], 'admin@yourpaintedplate.com', NULL, 'Chapel Hill, NC', 'https://www.yourpaintedplate.com/chapelhillmealprep', 'active', NULL),
  ('2026-08-09T01:09:02.142187+00:00'::timestamptz, 'home-property-services/cleaning-services', 'Molly Maid of Chapel Hill', 'Locally owned, bonded and insured maid service serving Chapel Hill since 1997', 'Molly Maid of Chapel Hill is a locally owned and independently operated franchise that has served Orange, Durham, and Chatham counties since 1997. Services include one-time and recurring house cleaning (weekly, biweekly, or monthly), apartment and condo cleaning, move-in/move-out cleans, and light commercial work. Bonded and insured, with no long-term contracts required.', ARRAY['insured', 'bonded', 'recurring', 'move-out', 'franchise']::text[], NULL, '(919) 328-2286', 'Chapel Hill, NC', 'https://www.mollymaid.com/locations/chapel-hill/', 'active', NULL),
  ('2026-08-09T01:09:02.244895+00:00'::timestamptz, 'home-property-services/cleaning-services', 'The Cleaning Authority - Chapel Hill', 'Family-owned maid service with a detail-rotation cleaning system and eco-friendly products', 'Family owned and operated, The Cleaning Authority - Chapel Hill serves Chapel Hill, Carrboro, Pittsboro, Hillsborough, and Durham. They use a rotating "Detail-Clean" system so different areas of the home get deep attention on each visit, and they clean with environmentally responsible products. Free in-home estimates are available.', ARRAY['family-owned', 'eco-friendly', 'recurring', 'free-estimate']::text[], NULL, '(919) 648-0523', 'Chapel Hill & Pittsboro, NC', 'https://www.thecleaningauthority.com/chapelhill/', 'active', NULL),
  ('2026-08-09T01:09:02.32074+00:00'::timestamptz, 'home-property-services/cleaning-services', 'Enovana Green Cleaning', 'Eco-friendly house cleaning with upfront online pricing, serving Briar Chapel since 2007', 'Enovana Green Cleaning has provided green residential cleaning across the Triangle since 2007 and lists Briar Chapel among the neighborhoods it serves. Offerings include recurring weekly, biweekly, and monthly service, one-time deep cleans, move-in/move-out cleaning, and custom requests such as extra attention to baseboards or bathrooms. Booking is done online with upfront pricing and same-day scheduling of your preferred time slot.', ARRAY['eco-friendly', 'green', 'online-booking', 'recurring', 'deep-clean']::text[], 'raleigh@enovanagreencleaning.com', '(919) 801-8588', 'Chapel Hill & Briar Chapel, NC', 'https://enovanagreencleaning.com/chapel-hill-cleaning-services/', 'active', NULL),
  ('2026-08-09T01:09:02.395277+00:00'::timestamptz, 'home-property-services/cleaning-services', 'MaidPro Chapel Hill', 'Customizable maid service built on a 49-point checklist, serving Briar Chapel and nearby neighborhoods', 'MaidPro Chapel Hill cleans single-family homes, townhouses, condos, and apartments, and specifically names Briar Chapel, Meadowmont, Winmore, Governors Club, and Sunset Creek among its service areas. Every clean follows a 49-Point Checklist that can be customized with special instructions for any visit. Weekly, biweekly, monthly, and one-time cleanings are available with no long-term contract.', ARRAY['checklist', 'customizable', 'recurring', 'one-time', 'no-contract']::text[], NULL, '(919) 942-9339', 'Chapel Hill, NC', 'https://www.maidpro.com/chapelhill', 'active', NULL),
  ('2026-08-09T01:09:02.462339+00:00'::timestamptz, 'home-property-services/cleaning-services', 'Sylvia Cleaning of Chapel Hill', 'Small locally owned maid service run by a longtime Carrboro resident, serving Briar Chapel', 'Sylvia Cleaning is a locally owned and operated maid service that has worked in Chapel Hill, Carrboro, Durham, and surrounding Orange County communities since 2010, and lists Briar Chapel among the neighborhoods it covers. Services include recurring weekly, biweekly, and monthly cleaning, one-time deep cleaning, move-in/move-out turnovers, and office and apartment cleaning, with eco-friendly products available on request. Quotes are provided upfront with no hidden fees.', ARRAY['local', 'small-business', 'eco-friendly-option', 'deep-clean', 'move-out']::text[], 'SilviaCleaningserv@gmail.com', '(919) 265-8859', 'Chapel Hill & Carrboro, NC', 'https://www.sylvianc.com/', 'active', NULL),
