  ('2026-05-16T02:53:04.092461+00:00'::timestamptz, 'home-property-services/roofing-painting-carpentry', 'Gonzalez Painters & Contractors, Inc.', 'Local Triangle painting, roofing, gutters, siding, and drywall contractor', 'Interior painting, exterior painting, commercial painting, cabinet painting, deck/fence staining, roof replacement, roof repair, EPDM rubber roof installation, skylight replacement, gutters, siding, drywall, popcorn ceiling removal.', '{}'::text[], 'Gonzalez@fgpainting.com', '(919) 477-6058', 'Durham', 'https://fgpainting.com/', 'active', 'https://images.briarchapelconnect.com/service-images/catalog/roofing-painting-carpentry/gonzalez-painters-and-contractors-inc.webp'),
