  ('2026-05-16T03:06:16.875111+00:00'::timestamptz, 'home-property-services/roofing-painting-carpentry', 'B&G Home Improvement Inc.', 'Carrboro North home remodeling, painting, siding, and roofing/home improvement contractor serving Carrboro, Chapel Hill, Durham, and surrounding areas.', 'Commercial painting, exterior painting, house painting, interior painting, roof repair, roof restoration, roofing, residential roofing, residential roof repair, siding, remodeling, decks, flooring, windows, restoration.', '{}'::text[], 'manny@bghomeimprovement.com', '(919) 224-7615', 'Carrboro', 'https://bghomimp.com/', 'active', 'https://images.briarchapelconnect.com/service-images/catalog/roofing-painting-carpentry/b-and-g-home-improvement-inc.webp'),
  ('2026-08-11T00:25:57.85142+00:00'::timestamptz, 'pet-services/dog-walking-pet-sitting', 'Cats@Home', 'In-home cat care based in North Chatham, with Briar Chapel named in its service area', 'Cats@Home is a North Chatham business specializing exclusively in in-home care for cats, operating since 2000 under owner Kristin White del Rosso. She is a certified pet sitter with both Pet Sitters International and the National Association of Professional Pet Sitters. The published service area names Briar Chapel directly, along with Chatham Forest, Fearrington, Governors Club, Lystra Preserve, Potters Ridge, Powell Place, Southern Village, and Westfall. Because coverage varies by address, the business asks prospective clients to confirm their location before booking.', ARRAY['cat-care', 'in-home', 'briar-chapel', 'certified', 'established']::text[], NULL, NULL, 'North Chatham & Briar Chapel, NC', 'https://catsathomenc.com/', 'active', NULL),
  ('2026-08-11T00:25:57.91692+00:00'::timestamptz, 'pet-services/dog-walking-pet-sitting', 'Walk & Wag', 'Chapel Hill and Carrboro dog walking and pet sitting company operating since 2010', 'Walk & Wag has cared for pets in the Chapel Hill and Carrboro area since 2010 under owner Lisa Kang, who hand-picks the team of professional walkers and sitters. The company is licensed, bonded, and insured through Business Insurers of the Carolinas and is recommended by local veterinarians. Services include one-on-one dog walks, cat visits, care for other animals such as chickens or fish, vacation visits, overnight stays, a pet taxi to vet and groomer appointments, and a pet concierge service for picking up supplies. Clients receive a daily report with walk lengths, locations, feedings, photos, and short videos through the Time To Pet portal. A surcharge may apply for outlying locations.', ARRAY['dog-walking', 'pet-sitting', 'bonded', 'insured', 'pet-taxi']::text[], 'lisa@walkandwagchapelhill.com', '(919) 619-4456', 'Chapel Hill & Carrboro, NC', 'https://walkandwagchapelhill.com/', 'active', NULL),
  ('2026-08-11T00:25:57.982905+00:00'::timestamptz, 'pet-services/dog-walking-pet-sitting', 'Kate''s Critter Care', 'Veterinarian-recommended dog walking and in-home pet sitting, established 2008', 'Kate''s Critter Care has provided dog walking and in-home pet sitting in Carrboro, Chapel Hill, and South Durham since 2008, owned and operated by Kate Turlington. The company is licensed and insured, veterinarian recommended, and certified in American Red Cross Pet First Aid and CPR. Services are fully customizable and range from a single mid-day walk to 24-hour live-in care, and include fresh food and water, potty breaks, playtime, medication administration, litter box and crate maintenance, and cleanup of pet-related accidents. New clients start with a short questionnaire about their animals and reservation needs.', ARRAY['dog-walking', 'pet-sitting', 'insured', 'pet-first-aid', 'overnight']::text[], NULL, '(919) 943-8083', 'Carrboro & Chapel Hill, NC', 'https://katescrittercare.com/', 'active', NULL),
  ('2026-08-11T00:25:58.048231+00:00'::timestamptz, 'pet-services/dog-walking-pet-sitting', 'Kaitlyn''s Kuddles Pet Services', 'Insured and bonded in-home pet sitting and dog walking across Chapel Hill and Carrboro', 'Kaitlyn''s Kuddles Pet Services provides in-home pet sitting, dog sitting, and dog walking throughout Chapel Hill, Carrboro, Durham, and Morrisville. Sitters are trained and background checked, and the business is fully insured and bonded. Visits are built around each pet''s existing routine and include feeding, playtime, litter and waste cleanup, and photo updates after each visit. Dog walks cover leash walks and potty breaks with activity updates. Rates are set by visit duration and care needs, and the company also offers house care while clients are away.', ARRAY['pet-sitting', 'dog-walking', 'insured', 'bonded', 'background-checked']::text[], NULL, '(919) 804-8944', 'Chapel Hill & Carrboro, NC', 'https://www.kaitlynskuddles.com/', 'active', NULL),
  ('2026-08-11T00:25:58.114732+00:00'::timestamptz, 'pet-services/dog-walking-pet-sitting', 'Nose, Toes & Tails Pet Care', 'Locally owned pet sitting, dog walking, and pet transport serving Chapel Hill since 2018', 'Nose, Toes & Tails Pet Care is a locally owned business created in 2018 and based in Haw River, serving Chapel Hill, Carrboro, Durham, and Hillsborough along with Mebane, Burlington, and Graham. Services cover pet sitting, dog walking, and pet transport. Because the company is based further north than most options on this list, Chapel Hill sits toward the southern edge of its coverage, so confirming availability for a specific address is worthwhile.', ARRAY['pet-sitting', 'dog-walking', 'pet-transport', 'local', 'orange-county']::text[], NULL, '(919) 418-3899', 'Chapel Hill & Hillsborough, NC', 'https://www.nosetoestails.com/', 'active', NULL),
  ('2026-08-11T00:24:28.608112+00:00'::timestamptz, 'pet-services/local-veterinarians', 'Cole Park Veterinary Hospital', 'Full-service small animal hospital on Woodbridge Drive, inside the 27516 ZIP code', 'Cole Park Veterinary Hospital is a full-service veterinary medical facility on Woodbridge Drive in Chapel Hill, one of the few practices with a 27516 address. The practice provides medical, surgical, and dental care for dogs and cats, with an emphasis on preventative health care and client education. For emergencies outside business hours the hospital refers clients to BluePearl in Cary or Triangle Veterinary Referral Hospital in Durham, and to UrgentVet in Chapel Hill for non-life-threatening issues.', ARRAY['small-animal', 'surgery', 'dental', 'preventative', '27516']::text[], NULL, '(919) 929-3352', 'Chapel Hill, NC', 'https://coleparkvet.com/', 'active', NULL),
  ('2026-08-11T00:24:28.740611+00:00'::timestamptz, 'pet-services/local-veterinarians', 'Meadowmont Animal Hospital', 'Independent Chapel Hill practice on Finley Golf Course Road with same-day sick visits', 'Meadowmont Animal Hospital is an independently owned practice on Finley Golf Course Road that has served Chapel Hill for over a decade. Services include wellness care, same-day sick visits, veterinary dentistry, surgery, urgent care, daytime hospitalization, and referral to specialists for after-hours needs. The practice treats dogs and cats and serves Chapel Hill, Carrboro, Hillsborough, Durham, and the greater Orange and Chatham county area. It has been recognized with local Best Veterinarian and Best of Chapel Hill awards.', ARRAY['independent', 'same-day', 'dentistry', 'surgery', 'urgent-care']::text[], 'welovepets@meadowmontah.com', '(919) 951-7851', 'Chapel Hill, NC', 'https://meadowmontah.com/', 'active', NULL),
  ('2026-08-11T00:24:28.804769+00:00'::timestamptz, 'pet-services/local-veterinarians', 'Vine Veterinary Hospital & Surgical Center', 'Independently owned Carrboro–Chapel Hill hospital offering same-day appointments and walk-ins', 'Vine Veterinary Hospital & Surgical Center is an independently owned animal hospital serving the Carrboro and Chapel Hill community. It offers a full range of preventive and advanced veterinary care alongside an on-site surgical center. The practice accepts same-day appointments and welcomes walk-ins during regular business hours, and asks that clients call ahead for urgent cases so the team can prepare for arrival. Appointments can be requested by phone, text, or through an online form.', ARRAY['independent', 'surgery', 'walk-ins', 'same-day', 'preventive']::text[], NULL, '(919) 942-5117', 'Chapel Hill, NC', 'https://vineveterinaryhospital.com/', 'active', NULL),
  ('2026-08-11T00:24:28.870918+00:00'::timestamptz, 'pet-services/local-veterinarians', 'Kindred Heart Animal Hospital', 'Two-location practice with clinics in Carrboro and at Governors Village in Chapel Hill', 'Kindred Heart Animal Hospital operates two clinics, one on Two Hills Drive in Carrboro and one at Governors Village on Governors Drive in Chapel Hill. Services span routine wellness exams and vaccinations through advanced diagnostics, dermatology, dental care, senior pet care, and surgical procedures. The Chapel Hill location is the more convenient of the two for residents south of town. Each clinic maintains its own direct phone line; the Chapel Hill office can be reached at (919) 756-7680.', ARRAY['two-locations', 'wellness', 'dermatology', 'dental', 'senior-care']::text[], NULL, '(919) 525-1962', 'Carrboro & Chapel Hill, NC', 'https://kindredheartvet.com/', 'active', NULL),
  ('2026-08-11T00:24:28.936238+00:00'::timestamptz, 'pet-services/local-veterinarians', 'UrgentVet Chapel Hill', 'After-hours and weekend urgent care for dogs and cats, with walk-ins and online check-in', 'UrgentVet Chapel Hill provides after-hours and weekend urgent care for sick or injured dogs and cats from a location on Fordham Boulevard. It fills the gap between a regular veterinary practice and a full emergency hospital, handling non-life-threatening issues that cannot wait for a routine appointment. Clients can walk in or reserve a spot online ahead of arrival. Several area practices, including Cole Park Veterinary Hospital, refer clients here for non-emergency after-hours needs, while true emergencies are directed to BluePearl in Cary or Triangle Veterinary Referral Hospital in Durham.', ARRAY['urgent-care', 'after-hours', 'weekend', 'walk-in', 'dogs-cats']::text[], NULL, '(984) 261-2323', 'Chapel Hill, NC', 'https://www.urgentvet.com/chapel-hill/', 'active', NULL),
  ('2026-08-11T00:25:35.512209+00:00'::timestamptz, 'pet-services/pet-grooming-boarding', 'Green Beagle Lodge - Chapel Hill', 'Award-winning all-inclusive pet lodge on Millhouse Road offering boarding, daycare, and grooming', 'Green Beagle Lodge opened in Chapel Hill in 2014 and offers boarding, daycare, grooming and bathing, and training from its Millhouse Road facility inside 27516. Lodging is all-inclusive with no added fees for feeding, playtime, or medication administration, and includes twice-daily health checks and supervised outdoor play. Dogs are grouped for play by temperament, size, and activity level, and every new dog completes a half-day on-site assessment before their first boarding or daycare stay. The lodge won the Chamber of Commerce inaugural New Business of the Year award and has taken awards from Chapelboro, The Independent, and the Chamber in the years since.', ARRAY['boarding', 'daycare', 'grooming', 'all-inclusive', 'local']::text[], 'chapelhill@greenbeaglelodge.com', '(919) 929-7387', 'Chapel Hill, NC', 'https://greenbeaglelodge.com/chapelhill/', 'active', NULL),
  ('2026-08-11T00:25:35.584182+00:00'::timestamptz, 'pet-services/pet-grooming-boarding', 'Green Beagle Lodge - Pittsboro', 'Sister facility on a 13-acre Chatham County tract, roughly 18 minutes from Briar Chapel', 'The Pittsboro location of Green Beagle Lodge opened in December 2022 and is the closest of the two facilities to Briar Chapel, at roughly 18 minutes away. It occupies an 11,000 square foot building on a 13-acre tract on the eastern edge of Chatham Park, just above Route 64. Services match the Chapel Hill lodge: all-inclusive boarding, daycare, grooming and bathing, and training, with an emphasis on active social play in outdoor yards. Staff receive extensive training in reading canine body language and managing off-leash play groups, and the lodge accommodates dogs with dietary restrictions or limited exercise requirements.', ARRAY['boarding', 'daycare', 'grooming', 'chatham-county', 'training']::text[], 'pittsboro@greenbeaglelodge.com', '(919) 929-7387', 'Pittsboro, NC', 'https://greenbeaglelodge.com/pittsboro/', 'active', NULL),
  ('2026-08-11T00:25:35.647561+00:00'::timestamptz, 'pet-services/pet-grooming-boarding', 'Woof Gang Bakery & Grooming Chapel Hill', 'Women-owned full-service grooming salon and pet store on Environ Way', 'Woof Gang Bakery & Grooming Chapel Hill is a full-service grooming salon and neighborhood pet store on Environ Way. Grooming covers all breeds and sizes and includes bathing, haircuts, nail trimming, ear cleaning, sanitary trims, and specialized treatments such as de-shedding. The store also carries all-natural chews, treats, pet food, toys, and accessories. The business identifies as women-owned and holds a 4.8 star average across roughly 296 reviews. Appointments are strongly recommended over walk-ins.', ARRAY['grooming', 'women-owned', 'pet-store', 'all-breeds', 'appointment']::text[], NULL, '(919) 869-7265', 'Chapel Hill, NC', 'https://woofgangbakery.com/pages/locations/chapel-hill', 'active', NULL),
  ('2026-08-11T00:25:35.711725+00:00'::timestamptz, 'pet-services/pet-grooming-boarding', 'Dogwood Veterinary Hospital & Pet Resort', 'Veterinary-supervised boarding, daycare, and grooming attached to a full-service animal hospital', 'Dogwood Veterinary Hospital & Pet Resort on Vickers Road combines a full-service veterinary practice with a pet resort offering boarding, daycare, bathing, and grooming for cats and dogs. Because boarding is veterinary-supervised, the resort can handle medication administration and special dietary support alongside private kennels or suites, fresh bedding, and supervised outdoor time. Grooming is tailored to breed and coat type, from routine clean-ups to breed-specific haircuts and help with matting or overgrown nails. Optional bathing or grooming can be added before pick-up from a boarding stay.', ARRAY['boarding', 'grooming', 'daycare', 'veterinary-supervised', 'medication']::text[], NULL, '(919) 942-6330', 'Chapel Hill, NC', 'https://www.dogwoodvethospital.com/services/pet-boarding-grooming/', 'active', NULL),
  ('2026-08-11T00:25:35.777252+00:00'::timestamptz, 'pet-services/pet-grooming-boarding', 'Noah''s Ark Kennel and Cattery', 'Long-running East Franklin Street boarding kennel and cattery serving the area since 1997', 'Noah''s Ark Kennel and Cattery has provided pet boarding and pet sitting for Chapel Hill, Carrboro, and Durham since 1997, operating from East Franklin Street. The facility boards both cats and dogs, with the cattery run as a distinct space from the dog kennel. The business reopened under continued operation in February 2019 after a break. It is one of the longer-established boarding options in the immediate Chapel Hill area.', ARRAY['boarding', 'cattery', 'kennel', 'established', 'pet-sitting']::text[], NULL, '(919) 932-7322', 'Chapel Hill, NC', 'https://noahsarkkennel.com/', 'active', NULL),
  ('2026-08-11T00:25:44.098272+00:00'::timestamptz, 'pet-services/pet-training', 'Hearth and Hounds', 'Chapel Hill trainers offering force-free private lessons and Canine Good Citizen prep', 'Hearth and Hounds is a Chapel Hill dog training business led by two certified professional trainers, Susan Spinks and Melanie Berk. Both hold the CPDT-KA credential and use only positive, force-free, reward-based methods. Susan completed Levels 1 and 2 of the Pat Miller Canine Behavior and Training Academy, is an AKC Canine Good Citizen Evaluator, and managed the dog training program at Paws4ever from 2020 to 2022. Melanie holds a Master’s in Animals and Public Policy from Tufts, is a Certified Canine Enrichment Technician, and has over 12 years of experience with shy and anxious dogs. They offer private in-home and public-space sessions, group classes at client locations, and structured Canine Good Citizen preparation, and specialize in puppies, fearful dogs, reactivity, and leash pulling.', ARRAY['cpdt-ka', 'force-free', 'private-lessons', 'canine-good-citizen', 'reactivity']::text[], NULL, '(919) 355-5656', 'Chapel Hill, NC', 'https://www.hearthandhounds.com/', 'active', NULL),
  ('2026-08-11T00:25:44.17294+00:00'::timestamptz, 'pet-services/pet-training', 'Pet Behavior Help', 'Training center offering group obedience classes and private behavior work with certified staff', 'Pet Behavior Help offers private dog training lessons and group classes from a location on Wendell Road, serving Chapel Hill, Durham, and Raleigh. Owner Val is a certified canine behavior specialist who takes private cases involving anxiety, reactivity, and aggression, working alongside a team of additional instructors. Group obedience classes focus on positive training techniques in a structured setting, and the center also runs rally and agility instruction. All ages, breeds, and skill levels are accepted.', ARRAY['obedience', 'group-classes', 'behavior', 'reactivity', 'agility']::text[], 'val@petbehaviorhelp.com', '(919) 270-2010', 'Chapel Hill, NC', 'https://petbehaviorhelp.com/', 'active', NULL),
  ('2026-08-11T00:25:44.241821+00:00'::timestamptz, 'pet-services/pet-training', 'Whole Dog Institute', 'Small-group obedience, nose work, and agility classes serving the Chapel Hill area', 'Whole Dog Institute serves the Durham, Chapel Hill, and Hillsborough area from a training facility on US Highway 70 Business. Founders Liz Turpin and Beth Grooms are both Certified Professional Dog Trainers Knowledge Assessed and Pat Miller Certified Trainers. Group classes are kept small at five to six dogs and cover puppy, teen, and adult obedience, reactive dog behavior modification, K9 Nose Work, agility, and therapy dog preparation. Private lessons are available in-home or at the facility, and the institute also runs a board and train program, rents training rings, and hosts drop-in puppy playtime for unvaccinated pups. The outdoor space includes agility fields.', ARRAY['cpdt-ka', 'small-classes', 'nose-work', 'agility', 'board-and-train']::text[], 'info@wholedoginstitute.com', '(919) 452-3764', 'Durham & Chapel Hill, NC', 'https://wholedoginstitute.com/', 'active', NULL),
  ('2026-08-11T00:25:44.31237+00:00'::timestamptz, 'pet-services/pet-training', 'Green Beagle Lodge Training', 'Obedience training run out of the Chapel Hill and Pittsboro pet lodges', 'Green Beagle Lodge offers dog training alongside its boarding, daycare, and grooming services at both its Chapel Hill facility on Millhouse Road and its Pittsboro facility on Lodge Lane. Working with the lodge trainers, owners learn both how to achieve obedience and how to better read and understand their dog. Because training runs out of facilities the dogs may already visit for daycare or boarding, it can be combined with a regular stay. The Pittsboro location is roughly 18 minutes from Briar Chapel and the Chapel Hill location sits within 27516.', ARRAY['obedience', 'facility-based', 'daycare-combo', 'local', 'two-locations']::text[], 'chapelhill@greenbeaglelodge.com', '(919) 929-7387', 'Chapel Hill & Pittsboro, NC', 'https://greenbeaglelodge.com/chapelhill/training/', 'active', NULL),
  ('2026-08-11T00:25:44.380075+00:00'::timestamptz, 'pet-services/pet-training', 'Carolina Dog Training', 'Private one-on-one and residency board-and-train programs covering the Chapel Hill area', 'Carolina Dog Training is led by Elaine Hope Poulin, a certified professional dog trainer, and serves the Raleigh, Durham, Cary, and Chapel Hill triangle from a base in Cary. The business focuses on private one-on-one instruction and residency board-and-train programs rather than group classes, and also covers family puppy orientation and therapy dog training. A related service, The Pack Sitters, offers dog walking and sitting with integrated training reinforcement for graduates of its programs. Because the business is based in Cary, Chapel Hill sits at the western edge of its service area, so confirming travel and availability is worthwhile.', ARRAY['private-training', 'board-and-train', 'puppy', 'therapy-dog', 'in-home']::text[], 'elaine@carolinadogtraining.com', '(919) 349-0000', 'Chapel Hill & Triangle, NC', 'https://carolinadogtraining.com/dog-training-chapel-hill-north-carolina/', 'active', NULL),
  ('2026-08-11T01:21:08.370828+00:00'::timestamptz, 'professional-miscellaneous/insurance-financial-advisors', 'McB Group Insurance Services', 'Independent Pittsboro insurance agency backed by Correll Insurance Group', 'McB Group Insurance Services operates from Lowes Drive in Pittsboro as an independent agency and a member of Correll Insurance Group, which has served the Carolinas for nearly 95 years. Being independent means the agency is not tied to a single carrier, so it can compare rates and coverage across a network of national carriers rather than offering one company’s product. It covers both personal and commercial lines including car, home, and business insurance. It is a Trusted Choice independent agency, and its primary market is Pittsboro, Siler City, Carrboro, Chapel Hill, Durham, and Raleigh.', ARRAY['independent-agency', 'pittsboro', 'home-auto', 'commercial', 'trusted-choice']::text[], 'info@mcbinsure.com', '(919) 642-0475', 'Pittsboro, NC', 'https://www.correllinsurance.com/insurance-offices/mcb-group-insurance-group-nc', 'active', NULL),
  ('2026-08-11T01:21:08.43784+00:00'::timestamptz, 'professional-miscellaneous/insurance-financial-advisors', 'High & Rubish Insurance Agency', 'Independent Chapel Hill agency covering auto, home, business, and farm insurance', 'High & Rubish Insurance Agency works from Farrington Road in Chapel Hill as an independent agency representing a selected group of financially strong carriers. Coverage spans auto, home, business, and farm insurance, with the farm line being relatively uncommon among Chapel Hill agencies and useful for properties on acreage around Chatham County. As an independent agent the office can approach several carriers to find competitive pricing and knows which carriers handle claims most efficiently. The agency is managed by Jeffrey A. Rubish. Office hours are Monday through Thursday 8:30am to 5pm and Friday 8:30am to 3pm, with a 24-hour online policy service center for payments, claims, and policy changes.', ARRAY['independent-agency', 'chapel-hill', 'farm-insurance', 'home-auto', 'business']::text[], NULL, '(919) 913-1144', 'Chapel Hill, NC', 'https://highandrubish.com/', 'active', NULL),
  ('2026-08-11T01:21:08.501722+00:00'::timestamptz, 'professional-miscellaneous/insurance-financial-advisors', 'Woodward Financial Advisors', 'Fiduciary wealth management firm at Glen Lennox offering ongoing planning and investment management', 'Woodward Financial Advisors is a fiduciary wealth management firm on Glen Lennox Drive in Chapel Hill. The firm performs ongoing financial planning together with investment management for its clients, and states plainly that it does not offer hourly or project-based engagements, so it is aimed at people seeking a continuing advisory relationship rather than a one-time plan. Prospective clients begin by scheduling an introductory conversation.', ARRAY['fiduciary', 'wealth-management', 'ongoing-planning', 'chapel-hill', 'investment-management']::text[], NULL, '(919) 929-2495', 'Chapel Hill, NC', 'https://woodwardadvisors.com/', 'active', NULL),
  ('2026-08-11T01:21:08.566749+00:00'::timestamptz, 'professional-miscellaneous/insurance-financial-advisors', 'Tarheel Advisors, LLC', 'Fee-only CFP practice on Market Street in Chapel Hill, serving clients since 2009', 'Tarheel Advisors has provided comprehensive financial planning and investment management to families and businesses since 2009, from an office on Market Street in Chapel Hill inside the 27516 ZIP code. The firm operates strictly fee-only and holds itself to fiduciary standards, working to eliminate conflicts of interest. It deliberately works with a small number of clients, and investment management clients receive planning services at no additional cost. Portfolios are customized, low-fee, and reviewed with clients at least annually, with attention to minimizing taxes. Advisors hold the CERTIFIED FINANCIAL PLANNER designation.', ARRAY['fee-only', 'cfp', 'fiduciary', 'chapel-hill', 'since-2009']::text[], NULL, '(984) 271-1993', 'Chapel Hill, NC', 'https://tarheeladvisors.com/', 'active', NULL),
  ('2026-08-11T01:21:08.631151+00:00'::timestamptz, 'professional-miscellaneous/insurance-financial-advisors', 'Master Plan Wealth Management', 'Fee-only Registered Investment Advisor whose founder lives in Pittsboro, meeting locally by arrangement', 'Master Plan Wealth Management is an independently owned, fee-only financial planning firm and Registered Investment Advisor operating as a fiduciary. Rather than requiring clients to travel to a single office, it holds meetings at locations across Chapel Hill, Raleigh, Durham, Cary, and Pittsboro, whichever is most convenient. President and founder Philip Royal is a CERTIFIED FINANCIAL PLANNER professional, an active member of the Financial Planning Association, and serves on a local community association finance committee. He lives in Pittsboro. Inquiries go through the website.', ARRAY['fee-only', 'fiduciary', 'cfp', 'pittsboro', 'flexible-meetings']::text[], NULL, NULL, 'Pittsboro, NC', 'https://masterplanwealth.com/', 'active', NULL),
  ('2026-08-11T01:21:16.027811+00:00'::timestamptz, 'professional-miscellaneous/legal-notary-services', 'Bradshaw Robinson Slawter & Rainer LLP', 'Pittsboro firm focused on real estate, land use and zoning, and business law', 'Bradshaw Robinson Slawter & Rainer LLP practices from the Hall-London House on Hillsboro Street in downtown Pittsboro, a Federal and Greek Revival home built in 1836 and listed on the National Register of Historic Places since 1982; the firm and its predecessors have occupied it since it was converted to offices in the 1980s. Practice areas cover real estate and finance including acquisition, financing, leasing, development, and sale of property; land use and zoning including subdivision and development regulations; and corporate and business law including entity formation, contracts, and asset purchases. Clients range from regional and national developers to small family-owned businesses and startups. The firm is centrally located between the Research Triangle and the Piedmont Triad.', ARRAY['real-estate-law', 'land-use', 'zoning', 'business-law', 'pittsboro']::text[], 'law@bradshawrobinson.com', '(919) 542-2400', 'Pittsboro, NC', 'https://brsrllp.com/', 'active', NULL),
  ('2026-08-11T01:21:16.092376+00:00'::timestamptz, 'professional-miscellaneous/legal-notary-services', 'Bagwell Holt Smith P.A.', 'Multi-practice firm with a Southern Village office, serving Chapel Hill and Pittsboro for 40+ years', 'Bagwell Holt Smith P.A. has served individuals, families, and businesses in the area for more than 40 years and keeps two Chapel Hill offices, one at Eastowne Office Park on Cloister Court and one in Southern Village on Market Street inside the 27516 ZIP code. Practice areas span residential and commercial real estate, estate planning and probate, family law, business law, community association law, civil litigation, personal injury, and workers’ compensation. Community association law is worth noting for residents of an HOA-governed neighborhood like Briar Chapel. Real estate and estate planning attorneys explicitly serve Pittsboro alongside Chapel Hill. The consultation fee for an initial estate administration meeting is $350, payable in advance.', ARRAY['estate-planning', 'real-estate-closings', 'hoa-law', 'southern-village', 'established']::text[], NULL, '(919) 932-2225', 'Chapel Hill, NC', 'https://bhspa.com/', 'active', NULL),
  ('2026-08-11T01:21:16.162529+00:00'::timestamptz, 'professional-miscellaneous/legal-notary-services', 'Hopper Cummings, PLLC', 'Family law and estate planning firm with deep Chatham County roots in downtown Pittsboro', 'Hopper Cummings, PLLC works from the historic Terry-Taylor House in downtown Pittsboro and serves clients throughout Chatham and Orange counties, including Chapel Hill, Hillsborough, and Siler City. Marie Hopper is a Chatham County native, a UNC School of Law graduate, and a former President of the 18th Judicial District Bar. Robert S. Cummings is a North Carolina native, a Campbell University School of Law graduate, and brings Board Certified Family Law credentials. Family law work covers divorce and separation, child custody and support, spousal support, domestic violence proceedings, adoption, and modification or enforcement of existing orders. Estate planning covers wills, trusts, powers of attorney, guardianship, and probate administration. The firm states its representation is built around resolution rather than prolonged litigation.', ARRAY['family-law', 'estate-planning', 'board-certified', 'probate', 'chatham-county']::text[], 'info@hoppercummings.com', '(919) 533-4115', 'Pittsboro, NC', 'https://hoppercummings.com/', 'active', NULL),
  ('2026-08-11T01:21:16.234086+00:00'::timestamptz, 'professional-miscellaneous/legal-notary-services', 'Ellis Family Law, P.L.L.C.', 'Board certified family law and estate planning boutique with a Pittsboro office on Hillsboro Street', 'Ellis Family Law, P.L.L.C. is a boutique family law and estate planning firm with a Pittsboro office on Hillsboro Street, alongside locations in Durham, Cary, and Wake Forest. The firm is led by board certified specialist Gray Ellis and has been named to the Legal Elite list of law firms by Business North Carolina. Family law work covers divorce, child custody and support, property division, spousal support, prenuptial agreements, high-asset and gray divorce, and LGBT family law matters. Estate planning covers wills, trusts, and powers of attorney, with the firm noting it applies knowledge of Chatham County property values, development trends, and local tax considerations to planning strategy. Clients speak directly with the attorney from the first consultation.', ARRAY['family-law', 'board-certified', 'estate-planning', 'divorce', 'pittsboro']::text[], NULL, '(919) 688-9400', 'Pittsboro, NC', 'https://ellisfamilylaw.com/pittsboro/family-law-attorneys/', 'active', NULL),
  ('2026-08-11T01:21:16.301866+00:00'::timestamptz, 'professional-miscellaneous/legal-notary-services', 'Law Offices of Doster & Brown, P.A.', 'Estate planning and probate practice on Hillsboro Street in Pittsboro, by appointment only', 'The Law Offices of Doster & Brown, P.A. maintain an office on Hillsboro Street in downtown Pittsboro handling estate planning and probate matters. The Pittsboro office operates by appointment only rather than keeping walk-in hours, so contact should be arranged in advance. Note that a direct phone number for this office was not published in the sources available, so reaching them may require going through their main practice contact.', ARRAY['estate-planning', 'probate', 'pittsboro', 'by-appointment', 'wills']::text[], NULL, NULL, 'Pittsboro, NC', NULL, 'active', NULL),
  ('2026-08-11T01:22:37.209723+00:00'::timestamptz, 'professional-miscellaneous/local-artisans-craftspeople', 'Chatham Artists Guild', 'Guild of 60-70 Chatham County visual artists behind the annual December Open Studio Tour', 'The Chatham Artists Guild is an organization of visual artists who live and work in Chatham County, currently around 60 to 70 members, and it is the best single starting point for finding local makers. Its signature event is the Annual Studio Tour, held the first two weekends each December, where artists open their private studios across the county for a free, self-guided drive through the countryside; the 2025 tour featured 59 artists across 41 studios. It is one of the oldest studio tours in the state and served as a prototype for others in the region. Individual artist pages on the Guild site include information about each maker and a gallery of their work, so the directory is useful year-round. Guild members also work as teaching artists and mentors through education outreach including the Annual Student Art Show and an Emerging Artists Program for Chatham and Orange high school students.', ARRAY['artist-guild', 'studio-tour', 'chatham-county', 'directory', 'nonprofit']::text[], 'chathamartists@gmail.com', '(919) 593-7541', 'Pittsboro, NC', 'https://chathamartistsguild.org/', 'active', NULL),
  ('2026-08-11T01:22:37.274611+00:00'::timestamptz, 'professional-miscellaneous/local-artisans-craftspeople', 'Mark Hewitt Pottery', 'Nationally recognized wood-fired pottery made in Pittsboro since 1983, open by appointment', 'Mark Hewitt has made functional and decorative pots in Pittsboro since 1983, using locally sourced North and South Carolina clays and glaze materials and firing them in one of two very large wood-burning kilns. His work blends Southern craft traditions with influences gathered studying pottery in Europe, Asia, Africa, Australia, and North America. He received a North Carolina Heritage Award and was honored at the Archie Bray Foundation in Montana for contributions to the ceramic arts. The barn and showroom is open year round by appointment, and twice a year the studio holds a Kiln Opening across two to three weekends, when 1500 or more freshly fired pots fill the barn and yard and visitors can meet Mark and see the kilns. Every pot is identified by maker, kiln, and date. Call to arrange a visit.', ARRAY['pottery', 'wood-fired', 'by-appointment', 'kiln-openings', 'award-winning']::text[], NULL, '(919) 542-2371', 'Pittsboro, NC', 'https://hewittpottery.com/', 'active', NULL),
  ('2026-08-11T01:22:37.337934+00:00'::timestamptz, 'professional-miscellaneous/local-artisans-craftspeople', 'Janet Resnik Pottery', 'Affordable functional stoneware from a Chatham County farm studio on Collins Mountain Road', 'Janet Resnik makes and sells functional stoneware designed and priced for everyday use, from a combined studio and gallery on a Chatham County farm on Collins Mountain Road. The work reflects its setting, with plates, mugs, bowls, pitchers, and platters featuring impressionistic landscape, animal, iris, and Christmas designs. Janet does all the wheel throwing and all the glazing, while assistants including her husband Mike work the slab roller. Pieces are bisque fired in a low-temperature electric kiln, then glazed and fired again at high temperature, mostly electric with a gas kiln for certain glazes. Prices are modest, with a spoon rest around $4, a dinner plate $24, and a large bowl or bird bath $65. Pottery is lead free, dishwasher safe, and oven safe if started cold. The studio is open Sundays and Wednesdays 3 to 6pm and by appointment. Note that credit cards are not accepted; there is a 20 percent discount for cash and 15 percent for checks, and pieces cannot be purchased online.', ARRAY['pottery', 'functional-stoneware', 'affordable', 'farm-studio', 'cash-or-check']::text[], NULL, '(919) 929-3324', 'Chapel Hill, NC', 'http://www.janetresnikpottery.com/', 'active', NULL),
  ('2026-08-11T01:22:37.414824+00:00'::timestamptz, 'professional-miscellaneous/local-artisans-craftspeople', 'Rudy Duo Studio', 'Pittsboro ceramics studio run by a husband-and-wife pair, collaborating with other local artists', 'Rudy Duo Studio is a Pittsboro art space run by Josh and Addie Rudy, a married couple whose primary focus is ceramics including sculpting, throwing, glazing, and kiln firing. Beyond their own ceramics work they collaborate with other artists across different media, with the stated aim of making more art forms accessible to people interested in trying them. The studio publishes a newsletter called Pottery Throw for updates on work and events. Contact is through the studio website.', ARRAY['ceramics', 'pittsboro', 'sculpture', 'collaborative', 'local-makers']::text[], NULL, NULL, 'Pittsboro, NC', 'https://www.rudyduostudio.com/', 'active', NULL),
  ('2026-08-11T01:22:37.478256+00:00'::timestamptz, 'professional-miscellaneous/local-artisans-craftspeople', 'Doug Dotson Pottery', 'Pittsboro studio potter making soda-fired functional ware and teaching soda firing classes', 'Doug Dotson is a studio potter in Pittsboro producing soda-fired functional pottery that he describes as earthy, lively, and usable. Soda firing is a distinctive process where soda is introduced into the kiln at high temperature, producing surface variation that differs piece to piece. Beyond selling his own work he teaches soda firing classes from the studio, which makes this a good option if you want to learn the process rather than just buy the results. He also exhibits at national ceramics shows. Updates on new work and upcoming classes go out through an email list on the website.', ARRAY['pottery', 'soda-fired', 'classes', 'pittsboro', 'functional-ware']::text[], NULL, NULL, 'Pittsboro, NC', 'https://dougdotsonpottery.com/', 'active', NULL),
  ('2026-08-11T01:21:01.16076+00:00'::timestamptz, 'professional-miscellaneous/real-estate-property-managers', 'Team Winkler - Briar Chapel Specialists', 'Briar Chapel residents and EcoBrokers who have sold over 350 homes in the community', 'Jennifer and Peter Winkler are licensed brokers who live in Briar Chapel and have sold over 350 homes within the community, making them the most established specialists in the neighborhood. Jen has been one of the top-selling brokers in Briar Chapel, was voted Chapel Hill’s Favorite Realtor by Chapel Hill Magazine readers in 2017 and 2018, and was named Briar Chapel’s Neighborhood Favorite agent by Nextdoor. She is a Certified EcoBroker with specialized training in the green-certified home construction required throughout Briar Chapel, and owns a green-certified home there with a 5kW solar PV system. The team maintains a dedicated Briar Chapel site covering amenities, the community map, and available homes, and refers clients to a preferred lender and closing attorney.', ARRAY['briar-chapel', 'ecobroker', 'green-homes', 'buyers-and-sellers', 'neighborhood-specialist']::text[], 'jen@teamwinkler.com', '(919) 593-3662', 'Briar Chapel, Chapel Hill, NC', 'https://www.briarchapelhomes.com/', 'active', NULL),
  ('2026-08-11T01:21:01.248961+00:00'::timestamptz, 'professional-miscellaneous/real-estate-property-managers', 'Chatham Homes Realty', 'The largest real estate firm in Chatham County, operating from Pittsboro since 2005', 'Chatham Homes Realty was founded in 2005 by owner-broker Kris Howard and has grown into the largest real estate firm in Chatham County, with its main office on West Street in Pittsboro plus locations in Siler City and Apex. The team covers residential, land, and EcoBroker specialties, working with buyers, sellers, and investors. With more than a dozen agents based in the Pittsboro office alone, it offers depth of local coverage that smaller firms cannot match. The firm also handles property management alongside brokerage.', ARRAY['pittsboro', 'largest-in-county', 'land-sales', 'ecobroker', 'property-management']::text[], NULL, '(919) 545-2333', 'Pittsboro, NC', 'https://www.chathamhomesrealty.com/', 'active', NULL),
  ('2026-08-11T01:21:01.317454+00:00'::timestamptz, 'professional-miscellaneous/real-estate-property-managers', 'Eric Andrews Realtor', 'Accredited Land Consultant and property management broker on Hillsboro Street in Pittsboro', 'Eric Andrews is an Accredited Land Consultant based on Hillsboro Street in Pittsboro and is the only Realtor in Pittsboro to hold the ALC accreditation, held by fewer than 500 Realtors nationwide. He specializes in land sales across the Piedmont region including Chatham and Orange counties. He was named a TCAR Elite Broker for both Land Sales and Property Management in 2023 and is a member of the North Carolina Association of Realtors Property Management Division, so he handles rental and investment property management alongside sales. He also serves on the Chatham County Planning Board, the UDO Chatham County sub-committee, and the Pittsboro Downtown Advisory Board, and is a licensed auctioneer.', ARRAY['land-sales', 'property-management', 'accredited-land-consultant', 'pittsboro', 'auctioneer']::text[], NULL, '(919) 548-1014', 'Pittsboro, NC', 'https://www.ericandrewsrealtor.com/', 'active', NULL),
  ('2026-08-11T01:21:01.388371+00:00'::timestamptz, 'professional-miscellaneous/real-estate-property-managers', 'Weaver Street Realty', 'Chapel Hill and Carrboro brokerage offering property management alongside sales', 'Weaver Street Realty is an established Chapel Hill and Carrboro area brokerage that handles property management in addition to residential sales. It is a long-standing local name in the Carrboro real estate market. Contact the office directly to confirm current property management availability and terms, as rental inventory in the area moves quickly.', ARRAY['property-management', 'carrboro', 'chapel-hill', 'residential-sales', 'local']::text[], NULL, '(919) 929-2020', 'Carrboro, NC', 'https://www.weaverstreetrealty.com/', 'active', NULL),
  ('2026-08-11T01:21:01.456767+00:00'::timestamptz, 'professional-miscellaneous/real-estate-property-managers', 'Red Door Company', 'Triangle property management and brokerage handling rentals across Chapel Hill and Chatham County', 'Red Door Company is a Triangle-based property management and real estate brokerage that lists and manages properties across Chapel Hill and the surrounding Chatham County area, including listings inside the 27516 and 27517 ZIP codes. The firm works with both owners looking to place a rental and buyers or sellers in the wider Triangle market. Its office is in Durham, so it is a regional operator rather than a Chatham County local, but it actively serves the Briar Chapel area.', ARRAY['property-management', 'rentals', 'triangle-wide', 'brokerage', 'investors']::text[], NULL, '(919) 321-0128', 'Durham, NC', 'https://reddoorcompany.com/', 'active', NULL),
  ('2026-08-11T01:21:23.011465+00:00'::timestamptz, 'professional-miscellaneous/tech-support-it-help', 'Chapel Hill Tech, LLC', 'On-site consulting for homes and small businesses from a 20-year local IT consultant', 'Chapel Hill Tech is the practice of David Alexander, who has consulted through it for more than 20 years, helping hundreds of regular clients in Chapel Hill and surrounding areas. He specializes in residential and small business support, working after hours alongside his day role as Chief Information Officer for a North Carolina state agency; he previously served as CIO for a local university. His credentials are unusually deep for residential work: a Business Information Technology degree from Virginia Tech, an MBA from UNC Kenan-Flagler, project management certifications including PMP and Project+, security certifications including CISSP, GCIH, and CISA, and general IT certifications including A+, Linux+, and ITIL. He has also worked as a factory-authorized repair technician for Apple, Dell, IBM, Lenovo, and HP hardware. Appointments are booked through the website.', ARRAY['residential', 'small-business', 'on-site', 'highly-certified', 'chapel-hill']::text[], NULL, NULL, 'Chapel Hill, NC', 'https://chapelhilltech.com/', 'active', NULL),
  ('2026-08-11T01:21:23.097586+00:00'::timestamptz, 'professional-miscellaneous/tech-support-it-help', 'Geeks on Call of the Triangle', 'On-site computer and server repair from an East Franklin Street office in Chapel Hill', 'Geeks on Call of the Triangle operates from East Franklin Street in Chapel Hill and specializes in coming to you rather than requiring you to drop equipment off, which avoids the multi-day turnaround typical of shop-based repair. Services cover on-site PC and server repair, software and hardware upgrades, managed IT services, cybersecurity, VoIP phone service, and data backup and recovery. The on-site model is aimed particularly at offices that cannot afford disruption while equipment is serviced.', ARRAY['on-site-repair', 'server-repair', 'managed-it', 'data-recovery', 'chapel-hill']::text[], 'elmer.hill@1844905geek.com', '(844) 905-4335', 'Chapel Hill, NC', 'https://www.1844905geek.com/', 'active', NULL),
  ('2026-08-11T01:21:23.170358+00:00'::timestamptz, 'professional-miscellaneous/tech-support-it-help', 'Computerbilities, Inc.', 'Managed IT services provider serving Chapel Hill small and medium businesses for over 30 years', 'Computerbilities has served small and medium-sized businesses in the Triangle for over 30 years, with Chapel Hill among its on-site service areas. The company provides fully managed IT services including a 24/7 help desk, on-site support, remote troubleshooting, cybersecurity, cloud services, backup solutions, and IT consulting. Its pitch is giving smaller organizations enterprise-grade technology capability without the cost of an in-house IT team, on predictable pricing. The office is based in Cary, so this is a regional provider rather than a Chatham County local, but it dispatches to Chapel Hill.', ARRAY['managed-it', 'business-focused', '24-7-helpdesk', 'cybersecurity', 'established']::text[], 'sales@computerbilities.com', '(919) 469-5060', 'Cary, NC', 'https://www.computerbilities.com/managed-it-services-chapel-hill-nc/', 'active', NULL),
  ('2026-08-11T01:21:23.24408+00:00'::timestamptz, 'professional-miscellaneous/tech-support-it-help', 'Petronella Technology Group', 'Remote-first managed IT and compliance services for Pittsboro and Chatham County businesses', 'Petronella Technology Group provides managed IT services to Pittsboro and Chatham County businesses on a remote-first model, with scheduled on-site support and same-business-day visits for critical issues. Services include remote and on-site help desk, hardware troubleshooting, software support, user account management, printer and peripheral support, and technology onboarding for new employees. Its remote monitoring and management platform gives 24/7 visibility into infrastructure, and the firm documents outcomes such as uptime and compliance in quarterly business reviews. The company notes relationships with Chatham County organizations spanning more than a decade, and is oriented toward the businesses arriving with Chatham Park development. Its office is 35 miles away in Raleigh.', ARRAY['managed-it', 'pittsboro', 'compliance', 'remote-monitoring', 'business-focused']::text[], NULL, NULL, 'Pittsboro, NC', 'https://petronellatech.com/it-support-pittsboro-nc/', 'active', NULL),
  ('2026-08-11T01:21:23.317043+00:00'::timestamptz, 'professional-miscellaneous/tech-support-it-help', 'Carolina Cell Phone Repairs', 'Walk-in device repair shop on West Franklin Street with free in-store diagnosis', 'Carolina Cell Phone Repairs is a storefront on West Franklin Street in Chapel Hill handling repairs for cell phones, iPads, tablets, computers, and laptops. Diagnosis in store is free, and the shop advertises low prices with evening hours running until 9pm, which makes it the practical option for a cracked screen or a dead laptop when you want a physical counter rather than scheduling an on-site visit. Call or stop in to confirm turnaround on your specific device.', ARRAY['walk-in', 'phone-repair', 'laptop-repair', 'free-diagnosis', 'chapel-hill']::text[], NULL, NULL, 'Chapel Hill, NC', NULL, 'active', NULL),
  ('2026-08-11T01:12:51.33242+00:00'::timestamptz, 'transportation-automotive/bike-repair-shops', 'The Bicycle Chain - Chapel Hill', 'West Franklin Street shop handling suspension rebuilds, custom wheel building, and frame overhauls', 'The Bicycle Chain on West Franklin Street in Chapel Hill goes well past standard tune-ups, offering suspension rebuilds and frame overhauls for Specialized and Cannondale full-suspension bikes, custom wheel building, disc brake service, and hub and pedal overhauls at sealed-bearing spec. Brands carried include Specialized, Cannondale, Gazelle, Benno, Surly, Juliana, 45NRTH, and Teravail, with components from Shimano and SRAM. The shop also assembles bikes bought elsewhere, with a standard fee of $150 and $260 for e-bikes, and runs a calendar of group rides and local cycling events. Hours are Monday through Friday 11am to 7pm, Saturday 10am to 6pm, and Sunday noon to 5pm.', ARRAY['suspension-service', 'custom-wheels', 'full-service', 'group-rides', 'chapel-hill']::text[], NULL, '(919) 929-0213', 'Chapel Hill, NC', 'https://thebicyclechain.com/', 'active', NULL),
  ('2026-08-11T01:12:51.39812+00:00'::timestamptz, 'transportation-automotive/bike-repair-shops', 'The Clean Machine', 'Carrboro shop with certified technicians, a Flat Club membership, and a bike trade-in program', 'The Clean Machine on West Main Street in Carrboro is part of a four-location operation across Chapel Hill and the wider Triangle. Certified technicians handle tune-ups and repairs, and the shop carries Surly bikes. Two things set it apart: a Flat Club membership that covers flat-tire fixes free for the life of the bike, and a trade-in program for old bicycles. The shop also hosts group rides, clinics, and special events announced through its email list. Hours vary, so it is worth calling ahead.', ARRAY['certified-techs', 'flat-club', 'trade-in', 'surly', 'carrboro']::text[], NULL, '(919) 967-5104', 'Carrboro, NC', 'https://thecleanmachine.com/', 'active', NULL),
  ('2026-08-11T01:12:51.462931+00:00'::timestamptz, 'transportation-automotive/bike-repair-shops', 'Back Alley Bikes', 'Service-focused downtown Carrboro shop taking walk-ins on all makes and models', 'Back Alley Bikes on Boyd Street in downtown Carrboro was founded specifically around service, aiming to be the area’s friendliest and highest quality full-service shop for all makes, models, and types of bicycles. Work ranges from suspension servicing for trail riders through simple gear adjustments for students to custom wheel builds for serious cyclists. Walk-ins are welcome, which is useful for quick fixes without booking ahead. The shop also runs group rides, clinics, and community events, and stocks bikes for sale.', ARRAY['walk-ins', 'all-brands', 'full-service', 'group-rides', 'carrboro']::text[], NULL, '(919) 967-7777', 'Carrboro, NC', 'https://www.backalleybikes.net/', 'active', NULL),
  ('2026-08-11T01:12:51.525536+00:00'::timestamptz, 'transportation-automotive/bike-repair-shops', 'Trek Bicycle Chapel Hill', 'Brand store on South Elliott Road offering sales and service', 'Trek Bicycle Chapel Hill on South Elliott Road is a Trek brand store handling both sales and service. As a manufacturer-operated location it is the natural stop for warranty work and parts on Trek bikes specifically, alongside general repair and tune-ups. It sits in the Elliott Road area convenient to central Chapel Hill.', ARRAY['trek', 'brand-store', 'sales-and-service', 'warranty-work', 'chapel-hill']::text[], NULL, '(919) 589-1609', 'Chapel Hill, NC', 'https://www.trekbikes.com/us/en_US/retail/chapel_hill/', 'active', NULL),
  ('2026-08-11T01:12:51.590624+00:00'::timestamptz, 'transportation-automotive/bike-repair-shops', 'Pittsboro eBikes', 'Electric bike rentals, sales, and service at The Plant in Pittsboro, the closest shop to Briar Chapel', 'Pittsboro eBikes operates out of The Plant on Lorax Lane in Pittsboro, a 17-acre business community that also houses several breweries, a distillery, and a coffee roaster. It is the closest bike shop to Briar Chapel. The business covers electric bike rentals, sales, and service, with online booking and same-day pickup for rentals. Published rental rates run $10 per day for an eScooter and $18 per day for an eBike in either 36V or 48V. Note this shop is oriented more toward e-bike rental and sales than general bicycle repair, so call ahead if you need service on a conventional bike.', ARRAY['e-bikes', 'rentals', 'pittsboro', 'the-plant', 'closest-to-briar-chapel']::text[], NULL, '(919) 533-9766', 'Pittsboro, NC', 'https://pittsboroebikes.com/', 'active', NULL),
  ('2026-08-11T01:12:31.433433+00:00'::timestamptz, 'transportation-automotive/mechanics-auto-detailing', 'Sanders Automotive', 'CARFAX Top Rated shop directly on US 15-501 North, rated 4.9 across 149 verified reviews', 'Sanders Automotive sits on US Highway 15-501 North in Pittsboro, placing it directly on the corridor Briar Chapel residents already drive. It is a CARFAX Top Rated Service Center holding a 4.9 out of 5 rating across 149 verified reviews. Commonly performed work includes brake service, oil changes, safety inspections, and tire service and repair. Reviewers repeatedly describe it as a genuine dealership alternative, citing detailed pre-appointment consultations that lay out the scope of work before anything begins.', ARRAY['15-501', 'carfax-top-rated', 'brakes', 'inspections', 'tires']::text[], NULL, '(919) 542-1386', 'Pittsboro, NC', 'https://www.sanders-auto.com/', 'active', NULL),
  ('2026-08-11T01:12:31.586082+00:00'::timestamptz, 'transportation-automotive/mechanics-auto-detailing', 'Chuy''s Auto Repair', 'Locally owned family shop on Sanford Road handling general repair and state inspections', 'Chuy''s Auto Repair is a locally owned family shop on Sanford Road in Pittsboro covering general maintenance and repair alongside state inspections. Reviews consistently emphasize honesty and unhurried service, with several customers noting the owner takes time to talk through work rather than rushing them, and one reporting a walk-in state inspection completed in under half an hour. The shop draws customers from across Chatham County and the surrounding communities including Chapel Hill and Carrboro. It is a good fit if you prefer a small independent shop over a chain.', ARRAY['pittsboro', 'family-owned', 'state-inspections', 'general-repair', 'walk-ins']::text[], NULL, '(919) 726-2000', 'Pittsboro, NC', 'https://www.chuysautorepairchatham.com/', 'active', NULL),
  ('2026-08-11T01:12:31.709928+00:00'::timestamptz, 'transportation-automotive/mechanics-auto-detailing', 'Doug''s Auto & Tire', 'Full-service shop and tire dealer backing repairs with a 2 year, 24,000-mile nationwide warranty', 'Doug''s Auto & Tire in Pittsboro handles everything from oil changes and state inspections through complete engine replacement, and backs all repairs with a 2 year, 24,000-mile nationwide warranty. The tire inventory covers cars, trucks, and SUVs from Cooper, Michelin, and Goodyear, and the shop also sells tractor tires for the local farming community. Doug grew up in Chatham County and chose the Pittsboro location specifically for its central access, reachable from Route 15-501 for Chapel Hill and Sanford drivers and from Routes 64 and 87 for Wake and Chatham County. Service area spans Pittsboro, Moncure, Siler City, Chapel Hill, Cary, Apex, Sanford, Raleigh, and Holly Springs.', ARRAY['nationwide-warranty', 'tires', 'engine-work', 'pittsboro', 'inspections']::text[], NULL, '(919) 542-5996', 'Pittsboro, NC', 'https://www.dougsautoonline.com/About', 'active', NULL),
  ('2026-08-11T01:12:31.82665+00:00'::timestamptz, 'transportation-automotive/mechanics-auto-detailing', 'Performance Automotive & Tire', 'Locally owned shop established in 1999, servicing hybrids and offering local drop-off and pickup', 'Performance Automotive & Tire on East Street in Pittsboro was established in 1999 and positions itself as a dealership alternative for Pittsboro, Chapel Hill, and Apex. The shop covers routine maintenance and repair across many makes and models including all hybrid models, and also handles passenger tires and aftermarket wheels, stocking BFGoodrich, Michelin, and Uniroyal. Customers living within Pittsboro city limits can be dropped off and picked up as a courtesy. Hours are Monday through Thursday 8am to 5pm and Friday 8am to 4pm.', ARRAY['established-1999', 'hybrid-service', 'tires', 'locally-owned', 'shuttle-service']::text[], NULL, '(919) 542-5614', 'Pittsboro, NC', 'https://www.performanceautomotiveandtire.com/', 'active', NULL),
  ('2026-08-11T01:12:31.93444+00:00'::timestamptz, 'transportation-automotive/mechanics-auto-detailing', '501 Auto Detailing', 'Car wash and detailing shop on US 15-501 between the Pittsboro circle and Chapel Hill', '501 Auto Detailing operates from US Highway 15-501 North in Pittsboro, sitting between the Pittsboro circle and Chapel Hill just south of Fearrington Village, which makes it the most convenient detailer to Briar Chapel. Three packages are offered: exterior detail, interior detail, and a combined full detail service. Exterior work starts with a foam cannon bath to lift dirt away from the paint before buffing minor scratches and finishing with polymer liquid wax. Interior service covers carpet vacuuming, floor mats, dash, seats, cupholders, and windows. Paint correction and ceramic coating can be added, with protection quoted up to five years. Hours are Monday through Thursday 8 to 5, Friday 8 to 4, and Saturday 8 to 2 by appointment.', ARRAY['detailing', '15-501', 'ceramic-coating', 'paint-correction', 'car-wash']::text[], NULL, '(919) 246-6129', 'Pittsboro, NC', 'https://www.501detailing.com/', 'active', NULL),
  ('2026-08-11T01:12:43.365399+00:00'::timestamptz, 'transportation-automotive/taxi-shuttle-services', 'Chatham Transit Network', 'Chatham County nonprofit running curb-to-curb rides and fixed routes to Chapel Hill from $2', 'Chatham Transit Network is a local non-profit providing public transportation throughout Chatham County, with fares starting at $2.00 each way for trips up to 3 miles and scaling to $7.00 for 10 to 13 miles. It runs two fixed routes, the PX Route and the 64 Route, giving regular weekday service between Siler City, Pittsboro, and Chapel Hill. It also operates an In-County Service providing curb-to-curb rides to and from any location in Chatham County, available 4am to 6pm daily, with reservations required at least 48 hours in advance. Monday requests must be in by noon the previous Thursday and Tuesday requests by noon the previous Friday. Vehicles are lift-equipped and accessible, and staff are screened and trained. The office on Dr. Martin Luther King Jr. Drive in Pittsboro is open weekdays 8am to 5pm.', ARRAY['nonprofit', 'chatham-county', 'accessible', 'low-cost', 'curb-to-curb']::text[], NULL, '(919) 542-5136', 'Pittsboro, NC', 'https://chathamtransit.org/', 'active', NULL),
  ('2026-08-11T01:12:43.486243+00:00'::timestamptz, 'transportation-automotive/taxi-shuttle-services', 'Carolina Sedan Service', 'Private black car service serving Pittsboro and RDU since 2008, bookable 24/7 by call or text', 'Carolina Sedan Service has provided private black car transportation around Chapel Hill, Carrboro, Durham, Raleigh, and RDU since 2008, and lists Pittsboro in its service area. Beyond airport transfers it handles medical and senior rides with reliable pickup windows, university travel for UNC and Duke visitors, and corporate and event service including hourly private drivers. Airport work includes meet-and-greet, luggage handling, and pickup times planned around your flight. Rides before 6am or after 10pm start around a $75 estimate. The office is on Colony Woods Drive in Chapel Hill and the company can be reached by call or text at any hour.', ARRAY['black-car', 'rdu-transfers', 'senior-rides', 'corporate', 'since-2008']::text[], 'booking@carolinasedan.com', '(919) 924-0568', 'Chapel Hill, NC', 'https://carolinasedan.com/', 'active', NULL),
  ('2026-08-11T01:12:43.598013+00:00'::timestamptz, 'transportation-automotive/taxi-shuttle-services', 'Chapel Hill Taxi & Airport Car Service', 'Triangle-wide taxi and car service operating 24/7 since 2003, including handicap transportation', 'Chapel Hill Taxi & Airport Car Service has served the Triangle since 2003 from the Hayes Building on Raleigh Road, covering Chapel Hill, Raleigh, Durham, Cary, and RDU Airport. Services extend past standard airport transfers to include corporate travel, special events, wedding limousine service, experiential city tours, handicap transportation, and nationwide transportation. The company operates 24 hours a day, seven days a week, including all holidays, with a separate booking line and office line.', ARRAY['24-7', 'rdu-transfers', 'handicap-accessible', 'limousine', 'since-2003']::text[], 'Booking@chapelhilltaxi.com', '(919) 933-9595', 'Chapel Hill, NC', 'https://chapelhilltaxi.com/', 'active', NULL),
  ('2026-08-11T01:12:43.695193+00:00'::timestamptz, 'transportation-automotive/taxi-shuttle-services', 'My RDU Airport Shuttle', 'Flat-rate RDU shuttle specializing in early morning pickups, with group vehicles up to 57 passengers', 'My RDU Airport Shuttle provides flat-rate, point-to-point shuttle transportation across the Raleigh-Durham and Chapel Hill regions with no surge pricing. The company specializes in early morning pickups and states that a 4am ride is as certain as a 4pm one, which suits catching first departures out of RDU. It handles individuals through groups of up to 57 passengers and also covers airport-to-airport transfers and luxury limousine service. Note that there is no counter on airport property, so travelers are asked to call on arrival; the company also sends a courtesy call or text once your flight lands if you provide airline and flight number when booking. Reservations can be made online, by phone, or by text, and the line is staffed 24/7.', ARRAY['flat-rate', 'early-morning', 'group-transport', '24-7', 'rdu']::text[], NULL, '(919) 728-0195', 'Chapel Hill, NC', 'https://www.myrduairportshuttle.com/', 'active', NULL),
  ('2026-08-11T01:12:43.763296+00:00'::timestamptz, 'transportation-automotive/taxi-shuttle-services', 'Yellow Chapel Hill RDU Taxi Cab', 'Door-to-door taxi with published flat rates to RDU, serving Chapel Hill, Carrboro, and Pittsboro', 'Yellow Chapel Hill RDU Taxi Cab runs door-to-door taxi service covering Chapel Hill, Carrboro, and Pittsboro, along with RDU airport pickups and drop-offs and out-of-town trips, operating 24 hours a day seven days a week. The company publishes specific flat rates to RDU rather than quoting on request, listing fares such as $44.95 from UNC and $49.95 from downtown Chapel Hill or UNC Hospital, though rates are subject to change. Rides can be booked through an online form or by phone.', ARRAY['flat-rate', 'rdu', '24-7', 'pittsboro', 'door-to-door']::text[], NULL, '(919) 928-5238', 'Chapel Hill, NC', 'https://yellowcabchapelhillrdutaxi.com/', 'active', NULL)
) AS v(created_at, category, title, summary, details, tags,
       contact_email, contact_phone, location, website, status, image_url)
WHERE NOT EXISTS (
  SELECT 1 FROM public.services s
   WHERE s.category = v.category AND s.title = v.title
);
